-- 프로토타입 위키(2장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('a6635f88-4eb9-5b54-b5b0-17702e7dc42c'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '포틀랜드시멘트', '석회석+점토를 소성한 클링커에 석고를 넣어 분쇄한 수경성 결합재. 콘크리트의 접착제 역할.', '["석고는 급결 방지(응결 조절)용 — ''왜 석고를 넣나''가 단골 질문."]'::jsonb, false),
  ('ca496836-7f4e-5924-9e85-9d3baa991054'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '보통포틀랜드시멘트 (1종)', '가장 일반적인 범용 시멘트. 특별한 요구가 없는 일반 구조물 전반에 사용.', '[]'::jsonb, false),
  ('c9a1aada-e685-5b62-994f-df2a5f36f6bc'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '중용열포틀랜드시멘트 (2종)', '수화열을 낮춘 시멘트. 초기강도는 느리지만 장기강도 우수, 건조수축 작음.', '["매스콘크리트·댐 등 수화열 균열이 걱정되는 부재에 사용."]'::jsonb, false),
  ('65feb9c8-1671-5821-b90e-7abd06b862d6'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '조강포틀랜드시멘트 (3종)', '분말도를 높여 초기강도 발현을 빠르게 한 시멘트.', '["한중공사·긴급공사·거푸집 조기 회전에 유리. 수화열이 커서 매스에는 부적합.", "비교·암기 — 2종(열 낮춤·느긋) ↔ 3종(빨리 굳음·뜨거움) — 반대 성격 짝."]'::jsonb, false),
  ('95e85adf-39dc-5a3f-8f20-dee32eb51906'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '저열포틀랜드시멘트 (4종)', '중용열보다 수화열을 더 낮춘 시멘트. 대규모 매스콘크리트용.', '[]'::jsonb, false),
  ('bac23561-25a8-58a6-a28d-2d2c03bc53b8'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 포틀랜드시멘트5종', '내황산염포틀랜드시멘트 (5종)', '황산염 저항성을 높인 시멘트(C3A 낮춤). 해안·온천·하수·토양 황산염 환경에 사용.', '[]'::jsonb, false),
  ('eb3111e0-d5fa-511e-9991-245f9dcce927'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '혼합시멘트', '포틀랜드시멘트에 혼화재(슬래그·플라이애시·포졸란)를 섞은 시멘트의 총칭. 장기강도·내구성·수화열 저감에 유리, 초기강도는 느림.', '[]'::jsonb, false),
  ('27267c7d-c02f-5481-b5bf-36ebfd769aaa'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '고로슬래그시멘트', '제철 부산물 고로슬래그 미분말을 혼합. 수화열 저감, 장기강도·해수 저항성 우수, 알칼리골재반응 억제.', '["초기강도 느림·중성화 속도 다소 빠름이 약점 — 양생 관리 중요."]'::jsonb, false),
  ('29fd5570-a4c3-55a4-8614-2f5ae88fec7d'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '플라이애시시멘트', '화력발전 부산물 플라이애시를 혼합. 볼베어링 효과로 워커빌리티 개선, 수화열 저감, 장기강도 증진.', '[]'::jsonb, false),
  ('4a457abe-a673-5f6f-ad59-5dcb16790854'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '포졸란시멘트', '천연·인공 포졸란을 혼합한 시멘트(실리카시멘트). 수밀성 향상, 장기강도형.', '[]'::jsonb, false),
  ('0cb95fc8-fad3-5053-997a-ed8556ff67cf'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '알루미나시멘트', '보크사이트+석회 원료의 초속경 시멘트. 1일에 보통시멘트 28일 강도 수준 — 긴급·한중·해수 공사용.', '["장기적으로 강도가 오히려 저하될 수 있어(전이) 구조용 사용에 신중."]'::jsonb, false),
  ('3d29000b-dab7-51a1-b50b-607e4bfdaf0c'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '팽창시멘트', '경화 중 약간 팽창하도록 만든 시멘트. 건조수축 보상용(수축보상 콘크리트).', '[]'::jsonb, false),
  ('ea858775-b040-58c3-a669-3e0d960090cc'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 혼합특수시멘트', '백색시멘트', '철분을 없애 하얗게 만든 시멘트. 착색·치장(테라조·미장) 용도.', '[]'::jsonb, false),
  ('20182f35-b52f-5083-aa2d-af750d513ed7'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '수화반응', '시멘트가 물과 반응해 수화물(C-S-H 겔 등)을 만들며 굳는 화학반응. 콘크리트 강도의 근원.', '[]'::jsonb, false),
  ('c36eb68c-9e43-50e5-a1d7-d1517a17e310'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '수화열', '수화반응에서 발생하는 열. 부재가 두꺼우면 내외부 온도차 → 온도균열의 원인.', '["비교·암기 — 수화열 대책 계보: 시멘트 선택(2·4종, 혼합) → 배합(단위시멘트량↓) → 시공(프리쿨링·파이프쿨링)."]'::jsonb, false),
  ('a2099916-0077-5e33-b9ee-4353f57303fd'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '응결 · 경화', '응결: 반죽이 유동성을 잃고 굳기 시작하는 초기 단계(초결~종결). 경화: 이후 강도가 계속 발현되는 과정.', '["응결 지연·촉진은 혼화재로 조절 — 콜드조인트·한중 관리와 직결."]'::jsonb, false),
  ('29b748e5-5b30-5364-8f2c-e5a5258a167e'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '분말도 (비표면적·블레인)', '시멘트 입자의 가늘기. 블레인 시험으로 비표면적(cm²/g) 측정.', '["분말도가 높으면: 수화 빠름·초기강도↑·워커빌리티↑, 대신 수화열↑·풍화 쉬움·건조수축↑."]'::jsonb, false),
  ('dbd8b76e-b409-50c2-b910-320fd3aa6f54'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '시멘트 풍화', '시멘트가 저장 중 공기 중 수분·CO2를 흡수해 굳거나 강도가 저하되는 현상.', '["대책: 방습 사일로·창고 보관, 선입선출, 지면 이격 적재. 풍화 의심 시 강열감량 시험."]'::jsonb, false),
  ('8cda6a38-7dba-5f89-a751-490e1cf0f371'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '안정성 (시멘트)', '경화 중 이상 팽창으로 균열·뒤틀림이 없는 성질. 유리석회 등 과다 시 불안정.', '["오토클레이브 팽창도 시험으로 판정."]'::jsonb, false),
  ('852c8bbb-b0d6-54a7-86b9-5eabe1141c10'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '비카트침 시험', '표준 침이 반죽에 들어가는 깊이로 시멘트의 표준주도(물량)와 응결시간(초결·종결)을 재는 시험.', '[]'::jsonb, false),
  ('673da68b-8388-5d25-8a9b-218ff2c10b5b'::uuid, '2장 · I 콘크리트재료 · 1절 · 시멘트 · 시멘트의성질시험', '오토클레이브 팽창도시험', '고온·고압 증기로 시멘트의 이상 팽창(안정성)을 단기간에 검사하는 시험.', '[]'::jsonb, false),
  ('4b10d82c-7bd6-5a3c-83ea-b0cb54bc2465'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '잔골재', '5mm 체를 거의 다 통과하는 골재(모래). ※경계 기준 정의 확인.', '["콘크리트 부피의 약 70%가 골재 — 골재 품질이 곧 콘크리트 품질."]'::jsonb, true),
  ('69363247-1143-59ab-b078-eb8232c5aefa'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '굵은골재', '5mm 체에 거의 다 남는 골재(자갈·쇄석).', '[]'::jsonb, false),
  ('625ca33a-5542-50a2-985c-b2c4fef0866b'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '굵은골재 최대치수', '골재가 질량으로 90% 이상 통과하는 체 중 최소 체 치수.', '["클수록 시멘트풀이 절약되나, 부재 치수·철근 간격·피복에 제약(간격의 일정 비율 이하 등). ※기준 확인."]'::jsonb, true),
  ('ad2a638f-68eb-57e7-ba90-4693a66f14b6'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '천연골재 · 부순골재 (쇄석)', '강모래·강자갈 등 천연산과, 암석을 깬 부순골재.', '["쇄석은 표면이 거칠어 부착강도 유리, 대신 워커빌리티 저하(단위수량 증가)."]'::jsonb, false),
  ('1048c435-4068-5ea0-8ca3-696adfe126bc'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '경량골재', '인공(팽창혈암·팽창점토) 또는 천연 경량 골재. 자중 저감·단열 목적, 흡수율이 커 프리웨팅(사전 흡수) 필요.', '[]'::jsonb, false),
  ('38f8b5e1-9f69-5bb4-8160-b6ff81ba2b1d'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '중량골재', '중정석·자철광 등 비중 큰 골재. 방사선 차폐용 중량콘크리트에 사용.', '[]'::jsonb, false),
  ('592d240b-4ffc-54b7-9f54-06870ed3fabc'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의구분', '순환골재', '폐콘크리트를 파쇄·가공한 재생 골재. 품질 기준 적합 시 용도별 사용 — 자원 순환 이슈와 연결.', '[]'::jsonb, false),
  ('d5ba455f-a0a2-5e6e-8540-25989126d220'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 입도밀도지표', '입도', '골재 크고 작은 입자의 혼합 비율. 입도가 좋으면(연속입도) 공극이 적고 시공성·경제성 우수.', '[]'::jsonb, false),
  ('094af35a-05aa-5e68-a4c5-e24ba212e56e'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 입도밀도지표', '조립률 (FM)', '표준체 10개에 남는 누적 백분율 합 ÷ 100. 골재의 평균 굵기 지표.', '["잔골재 FM 2.3~3.1 정도가 적정 범위로 통용. ※기준 확인."]'::jsonb, true),
  ('851bcb07-ce6a-5c9a-b1b3-f7c87b941495'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 입도밀도지표', '실적률', '골재를 용기에 채웠을 때 실제 골재가 차지하는 부피 백분율. 실적률↑ = 공극률↓ = 시멘트풀 절약·건조수축 감소.', '[]'::jsonb, false),
  ('cef3c51a-1e0d-5f3a-ac05-af37a9911d0e'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 입도밀도지표', '공극률 (골재)', '100 - 실적률. 골재 사이 빈틈의 비율.', '[]'::jsonb, false),
  ('b0b4c163-5354-571e-b3f5-032e297ca0b4'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 입도밀도지표', '단위용적질량', '1㎥ 용기에 채운 골재의 질량. 배합의 용적 환산에 사용.', '[]'::jsonb, false),
  ('5ebda4cd-d39b-54c2-9238-45e5b61b9528'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '절대건조상태 (절건)', '골재 내부 공극의 물까지 완전히 마른 상태(105℃ 건조).', '["비교·암기 — 절건 < 기건 < 표건 < 습윤. ''배합은 표건 기준, 현장은 표면수 보정'' 한 줄로 정리."]'::jsonb, false),
  ('83736ba2-7eb5-5478-af88-98ccece6067a'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '기건상태', '공기 중에서 자연 건조되어 내부에 약간의 수분이 남은 상태.', '[]'::jsonb, false),
  ('f083733c-08db-57c4-91cd-0a48834411fe'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '표면건조내부포수상태 (표건, SSD)', '표면은 말라 있고 내부 공극은 물로 가득 찬 상태.', '["배합설계의 기준 상태 — 골재가 배합수를 뺏지도 보태지도 않는 이상 상태."]'::jsonb, false),
  ('51875ab1-5c02-5b4c-9d70-db4b5daac860'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '습윤상태', '내부 포수 + 표면에도 물기가 있는 상태.', '[]'::jsonb, false),
  ('321dff3b-691d-5f52-83e9-933a4d5bff9a'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '흡수율', '절건 → 표건이 되는 데 흡수하는 물량의 백분율(내부 공극 크기의 지표). 흡수율 크면 골재 품질 낮음.', '[]'::jsonb, false),
  ('3d93aa9c-4312-5b77-b6d0-f1c6b4b2e9da'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '유효흡수량', '기건 상태 골재가 표건이 될 때까지 흡수하는 수량.', '[]'::jsonb, false),
  ('5049316d-3361-5f29-9ba0-7e4913dd4ec1'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의함수상태', '표면수율', '표건 이상으로 표면에 붙은 물의 비율. 현장배합에서 배합수를 그만큼 빼서 보정.', '[]'::jsonb, false),
  ('e4803143-0dc4-5f3f-a100-94066a7e5eb3'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의유해요소', '유해물질 (골재)', '점토덩어리·연한 석편·염화물·유기불순물 등 강도·내구성을 해치는 불순물. 한도 규정 있음. ※확인.', '[]'::jsonb, true),
  ('1fc5bca0-d2e5-5e29-ae73-505f5e5fbe15'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의유해요소', '염화물 함유량', '골재(특히 바다모래)의 염분. 철근 부식의 직접 원인 — 콘크리트 중 염화물 총량 규제. ※허용치 확인.', '[]'::jsonb, true),
  ('2295b043-5dca-5108-98b3-ac0e960b2a77'::uuid, '2장 · I 콘크리트재료 · 2절 · 골재 · 골재의유해요소', '알칼리골재반응 (AAR)', '시멘트의 알칼리와 골재의 반응성 실리카가 반응, 팽창성 겔을 만들어 콘크리트를 균열시키는 반응.', '["조건 3요소: 반응성 골재 + 높은 알칼리 + 수분. 대책: 저알칼리 시멘트, 혼합시멘트(슬래그·플라이애시), 반응성 골재 회피."]'::jsonb, false),
  ('8b59af22-6b01-571f-8a7d-4f1d47a0c9e7'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 물', '배합수', '콘크리트 비비기에 쓰는 물. 기름·산·염류·유기물 등 유해량이 없어야 함(상수도수 표준).', '[]'::jsonb, false),
  ('0666d03d-7147-5742-808a-3e1ab27af3f2'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 물', '회수수', '레미콘 설비 세척수에서 골재를 걸러낸 물(슬러지수·상징수). 품질 기준 내에서 재사용. ※기준 확인.', '[]'::jsonb, true),
  ('44d017a1-877a-57c4-b8f7-1a44d46998a2'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '혼화재 · 혼화제 구분', '혼화재(材): 시멘트 질량의 5% 이상, 배합 계산에 부피 산입(플라이애시·슬래그 등). 혼화제(劑): 1% 내외 소량, 부피 무시(AE제·감수제 등).', '["비교·암기 — ''재는 많이 넣는 재료, 제는 조금 넣는 약제'' — 산입 여부가 시험 포인트."]'::jsonb, false),
  ('c2fae00f-e461-5123-882f-b77e0469a0d8'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '플라이애시', '화력발전소 집진 미분탄재. 구형 입자의 볼베어링 효과로 워커빌리티 개선, 수화열 저감, 장기강도·수밀성 향상.', '["포졸란 반응(그 자체는 안 굳고 수산화칼슘과 반응해 굳음)."]'::jsonb, false),
  ('a629faf5-b29a-5b26-a031-cbd2420a5570'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '고로슬래그미분말', '고로 수쇄 슬래그의 미분말. 잠재수경성(자극받으면 스스로 굳는 성질)으로 장기강도·화학저항성 향상, 수화열 저감.', '["비교·암기 — 플라이애시=포졸란 반응 / 슬래그=잠재수경성 — 굳는 메커니즘 용어를 구분해 답하면 가점."]'::jsonb, false),
  ('4a0ed8d4-adf4-54c8-a8bb-3cb38f82efc2'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '실리카퓸', '실리콘 제련 부산물인 초미립 분말. 공극 충전+포졸란 반응으로 고강도·고수밀 실현.', '["고강도콘크리트 필수 재료. 단위수량 증가 → 고성능감수제와 세트 사용."]'::jsonb, false),
  ('09eb1ea0-19c3-5833-87bd-883ff7ae93d2'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '포졸란 · 포졸란반응', '그 자체는 수경성이 없지만 수산화칼슘과 반응해 불용성 수화물을 만드는 실리카질 재료(반응).', '[]'::jsonb, false),
  ('4ab3b613-b84e-5db2-996d-790068908260'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화재', '팽창재', '수화 시 팽창을 일으켜 건조수축을 보상하는 혼화재. 수축 균열 저감(수축보상·케미컬프리스트레스).', '[]'::jsonb, false),
  ('72f7ebe4-8291-5cfb-b36f-96294cf6cbd7'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', 'AE제 (공기연행제)', '미세 독립 기포를 콘크리트에 고르게 연행시키는 계면활성제.', '["효과: 워커빌리티 개선, 동결융해 저항성 대폭 향상(기포가 완충), 단위수량 감소. 공기량 1% 증가당 압축강도 약 4~6% 저하. ※수치 확인."]'::jsonb, true),
  ('4a7c647d-bd37-5e68-a5dd-443ae93541ee'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '연행공기 · 갇힌공기', '연행공기: AE제로 의도적으로 만든 미세·균일 기포(이로움). 갇힌공기: 비빔 중 자연히 들어간 큰 기포(해로움).', '["비교·암기 — ''만든 공기는 약, 갇힌 공기는 병'' — 같은 공기라도 크기·분포가 다르다."]'::jsonb, false),
  ('09d9c9b9-b8b8-56d8-9480-c6d7202e9d91'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '감수제', '시멘트 입자를 분산시켜 같은 워커빌리티를 더 적은 물로 얻게 하는 혼화제. 단위수량 감소 → 강도·내구성 향상.', '[]'::jsonb, false),
  ('60337301-4d06-53ac-87e0-8a651ea25f28'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', 'AE감수제', 'AE제+감수제 복합 성능. 현재 일반 레미콘의 표준 혼화제.', '[]'::jsonb, false),
  ('45460f46-962b-584e-9c2e-875d9b79985d'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '고성능감수제', '감수 성능을 대폭 높인 혼화제(폴리카본산계 등). 고강도·고유동 콘크리트의 핵심.', '["감수율 큰 순: 고성능감수제 > AE감수제 > 감수제."]'::jsonb, false),
  ('cda2b548-b1b0-5126-b3d2-e954b56ab2b9'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '고성능AE감수제', '고성능 감수 + 공기연행 + 슬럼프 유지 성능. 고내구성 콘크리트용.', '[]'::jsonb, false),
  ('1bacd334-62fc-5eef-bb5f-b28448ae065b'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '유동화제', '이미 비빈 콘크리트에 첨가해 물을 늘리지 않고 슬럼프를 일시적으로 크게 하는 혼화제.', '["비교·암기 — 감수제(물을 줄인다) ↔ 유동화제(물 안 늘리고 묽게 한다) — 목적·시점이 다름(공장 배합 vs 현장 첨가)."]'::jsonb, false),
  ('b8776671-b4c9-5f0a-b332-cdd1a0ff2eea'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '지연제', '응결을 늦추는 혼화제. 서중 콘크리트·장거리 운반·콜드조인트 방지·매스 연속타설에 사용.', '[]'::jsonb, false),
  ('44fe4596-e2d0-5b99-bdf4-8d980ad54e06'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '촉진제', '응결·경화를 빠르게 하는 혼화제. 한중 콘크리트·긴급공사에 사용.', '["염화칼슘계는 철근 부식 우려 — 사용 제한. ※규정 확인."]'::jsonb, true),
  ('0cc45754-1431-519d-8f1b-0ed047e8f671'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '급결제', '수 분 내 응결시키는 혼화제. 숏크리트(뿜어붙임)용.', '[]'::jsonb, false),
  ('4a5458fa-fc7f-5246-8c7b-62b559d6e9dc'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '방청제', '염화물 환경에서 철근 표면 부식을 억제하는 혼화제(아질산염계 등), 해사 사용·해양 구조물에 적용.', '[]'::jsonb, false),
  ('2531a302-0a7e-5d14-afd6-fac2769828aa'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '방수제 (혼화)', '콘크리트·모르타르의 흡수·투수를 줄이는 혼화제. 지하실 방수 모르타르 등에 사용.', '[]'::jsonb, false),
  ('101e216d-15aa-5c3d-8420-bb190f8c5960'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '수중불분리성혼화제', '점성을 높여 수중 타설 시 재료분리를 막는 혼화제. 수중콘크리트 전용.', '[]'::jsonb, false),
  ('1fa56232-1922-53ed-b61e-d66698a917db'::uuid, '2장 · I 콘크리트재료 · 3절 · 배합수혼화재료 · 혼화제', '발포제 · 기포제', '기포를 대량 발생시켜 경량기포콘크리트(ALC·경량 채움재)를 만드는 혼화제.', '[]'::jsonb, false),
  ('4eb9eb28-c076-593d-a829-2a522ac15c2c'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 워커빌리티계열', '워커빌리티 (시공연도)', '재료분리 없이 운반·타설·다짐·마감할 수 있는 작업 난이도의 종합 성질.', '["''반죽이 되냐 묽냐(컨시스턴시)''에 재료분리 저항성까지 포함한 상위 개념."]'::jsonb, false),
  ('8c89e942-6817-53f3-89fe-f581d2285d4d'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 워커빌리티계열', '컨시스턴시 (반죽질기)', '수량에 따른 반죽의 되고 묽은 정도. 슬럼프로 측정하는 바로 그 성질.', '[]'::jsonb, false),
  ('50cfdea1-5c50-5ef8-8b30-73ddeb6b96cd'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 워커빌리티계열', '플라스티시티 (성형성)', '거푸집에 잘 채워지고 흘러내리지 않으며 재료분리가 없는 성질.', '[]'::jsonb, false),
  ('45eb1ebd-6a66-5d15-b07b-bfc7f946c903'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 워커빌리티계열', '피니셔빌리티 (마감성)', '표면을 매끈하게 마감하기 쉬운 정도.', '[]'::jsonb, false),
  ('a9a6805a-0da0-52d8-9a0d-b5e6113995f9'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 워커빌리티계열', '펌퍼빌리티 (압송성)', '펌프로 막힘 없이 압송할 수 있는 성질.', '["비교·암기 — 다섯 용어 관계: 컨시스턴시(되기)를 바탕으로 워커빌리티(작업 전반)가 결정되고, 성형·마감·압송성은 국면별 성질."]'::jsonb, false),
  ('54aa0c48-d363-5fb1-93b5-714d13dbc222'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 시험', '슬럼프시험', '슬럼프콘에 3층×25회 다짐으로 채우고 들어 올려, 주저앉은 높이(cm)로 반죽질기를 재는 시험.', '["슬럼프가 크다 = 묽다. 부위·부재별 표준값은 시방 확인. ※"]'::jsonb, true),
  ('0166752b-bcc3-566a-8ac9-e7710875e95f'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 시험', '슬럼프플로 시험', '고유동 콘크리트가 퍼진 원의 지름(mm)으로 유동성을 재는 시험. 슬럼프로 측정 불가한 SCC용.', '[]'::jsonb, false),
  ('06c7bcc2-fe96-5898-ad16-2e50b0123f9d'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 시험', '공기량시험', '굳지 않은 콘크리트의 공기량(%)을 압력법 등으로 측정. AE 콘크리트 품질관리 항목. ※허용 범위 확인.', '[]'::jsonb, true),
  ('5ea3c4c1-781b-5e94-ba64-c42c0267165e'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 시험', '염화물량 시험', '굳지 않은 콘크리트의 염소이온량 측정. 철근 부식 예방 — 받아들이기 검사 항목. ※허용치 확인.', '[]'::jsonb, true),
  ('f35ba9aa-6026-5de3-b706-2393bb0e935a'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 초기결함현상', '블리딩', '타설 후 골재·시멘트가 가라앉으며 물이 표면으로 떠오르는 현상(재료분리의 일종).', '["과다 시: 표면 약화, 철근·골재 하부 수막(부착 저하), 침하균열, 레이턴스."]'::jsonb, false),
  ('ae40f948-542a-5edb-bb97-ce0a655d8d53'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 초기결함현상', '레이턴스', '블리딩수가 증발한 뒤 표면에 남는 미세물질의 약한 층.', '["이어치기 전 반드시 제거(치핑·와이어브러시) — 미제거 시 콜드조인트성 부착 불량."]'::jsonb, false),
  ('23c7fca0-5349-5708-a086-859104bd400a'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 초기결함현상', '재료분리', '굵은골재와 모르타르, 물과 고체가 분리되어 균질성을 잃는 현상. 원인: 과다 슬럼프·과다 낙하·과다 진동.', '["비교·암기 — 블리딩(물이 위로) ⊂ 재료분리(전반적 분리) — 포함 관계로 정리."]'::jsonb, false),
  ('5b0a6a78-3c67-5751-8b58-1623568a8b04'::uuid, '2장 · I 콘크리트재료 · 4절 · 굳지않은콘크리트 · 초기결함현상', '응결시간 (콘크리트)', '초결(작업 한계)·종결(굳음 시작)의 시간. 온도가 높을수록 짧아짐 — 이어치기 허용시간과 직결. ※시간 기준 확인.', '[]'::jsonb, true),
  ('4a9bd34c-259f-58be-8434-b10cd31ccd2b'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '배합설계', '요구 강도·내구성·워커빌리티를 최소 비용으로 만족하도록 재료 비율을 정하는 일.', '["큰 흐름: 배합강도 결정 → W/C(W/B) 결정 → 슬럼프·굵은골재 치수 → 단위수량 → 잔골재율 → 시방배합 → 현장배합 보정."]'::jsonb, false),
  ('226b5dfa-2f72-5038-a52a-787c91e158a2'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '물시멘트비 (W/C)', '물 무게 ÷ 시멘트 무게. 콘크리트 강도·내구성을 지배하는 가장 중요한 단일 변수.', '["W/C가 낮을수록 강도·내구성↑, 워커빌리티↓. ''강도는 물비가 결정한다''(아브람스 법칙)."]'::jsonb, false),
  ('6346b135-5edc-58ff-a26f-dde7d26683fa'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '물결합재비 (W/B)', '물 ÷ (시멘트+혼화재) 무게. 혼화재를 쓰는 현대 배합의 표준 표기.', '["비교·암기 — W/C에서 분모가 ''결합재 전체''로 확장된 것이 W/B."]'::jsonb, false),
  ('5babccca-c2fc-52f3-8c2c-61459e0a7265'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '단위수량', '콘크리트 1㎥에 들어가는 물의 양(kg/㎥). 가능한 한 적게가 원칙(건조수축·블리딩·강도 저하 방지). ※상한 기준 확인.', '[]'::jsonb, true),
  ('5b7f727d-4a6b-58df-ab92-53b102fe5e57'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '단위시멘트량', '1㎥당 시멘트량. 과다 시 수화열·수축 증가, 과소 시 강도·내구성·수밀성 부족. ※최소값 규정 확인.', '[]'::jsonb, true),
  ('5a348e67-5fe0-5a92-a413-25f8fe3f28dd'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '잔골재율 (S/a)', '전체 골재 절대용적 중 잔골재 절대용적의 백분율.', '["작게 할수록 단위수량·시멘트량 절감 가능하나, 너무 작으면 재료분리·거친 표면."]'::jsonb, false),
  ('d9e673e7-c22c-5c05-88d2-fb4bf0eab57d'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '시방배합 · 현장배합', '시방배합: 표건 골재·5mm 체 기준의 이상적 배합(시방서 지시). 현장배합: 현장 골재의 표면수·입도에 맞춰 보정한 실제 배합.', '["비교·암기 — ''설계실의 배합(시방) → 현장 사정 보정(현장)'' — 표면수 보정 계산이 시험 단골."]'::jsonb, false),
  ('878b3004-aa65-57dd-8468-d474d2e59b6a'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '설계기준압축강도 (fck)', '구조 설계에서 기준으로 삼는 콘크리트 압축강도(재령 28일 표준).', '[]'::jsonb, false),
  ('1d3e8fa7-e315-5d7e-aa29-1751eb17f651'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '배합강도 (fcr)', '배합을 정할 때 목표로 하는 강도. 품질 변동을 고려해 fck보다 크게 설정.', '["비교·암기 — fcr > fck — ''현장 편차가 있으니 여유를 두고 만든다''는 논리. 증가폭은 표준편차 기반 식으로. ※식 확인."]'::jsonb, true),
  ('29f121b3-d5e9-5e4f-83dd-9ae1635fa41d'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '호칭강도', '레미콘 주문 시 부르는 강도(kg 단위 규격 표기의 두 번째 숫자). 일반적으로 품질 기준이 되는 강도.', '[]'::jsonb, false),
  ('93987131-0106-573b-996b-98ca8da4c82e'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '레미콘 규격 표기법', '예: 25-24-150 = 굵은골재 최대치수 25mm - 호칭강도 24MPa - 슬럼프 150mm.', '["면접에서 ''25-24-150이 뭔가요'' 형태로 그대로 출제되는 단골."]'::jsonb, false),
  ('87b304cb-47c0-5da6-8923-badb3a9455ee'::uuid, '2장 · I 콘크리트재료 · 5절 · 배합설계', '표준편차와 강도 보정', '현장 품질 변동(표준편차)이 클수록 배합강도를 더 올려야 함 — 품질관리가 좋으면 시멘트를 아낀다는 논리.', '[]'::jsonb, false),
  ('9b3a4317-ca8e-5e3b-8fbf-fdd7f2c6008c'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '압축강도 (콘크리트)', '콘크리트의 대표 강도. 원주형 공시체(표준양생 28일)를 눌러 파괴할 때의 응력.', '["다른 강도(인장·휨·전단·탄성계수)도 압축강도와의 관계식으로 추정."]'::jsonb, false),
  ('af460324-d212-546c-afe3-bffa9251068c'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '인장강도 (콘크리트)', '압축강도의 약 1/10~1/13 수준으로 매우 약함 — 그래서 인장은 철근이 부담(RC의 존재 이유).', '[]'::jsonb, false),
  ('f0fe3923-6bb0-50a4-8cdd-4046a7aa0216'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '휨강도', '휨 부재(포장 등)의 균열 저항 지표. 압축강도의 1/5~1/8 수준.', '[]'::jsonb, false),
  ('c365c555-d406-53dd-bd51-e0adfd303a17'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '쪼갬인장강도시험', '원주 공시체를 옆으로 눕혀 쪼개 인장강도를 간접 측정하는 시험(할렬시험).', '[]'::jsonb, false),
  ('fa2e65c3-2ce8-58a5-bcd9-fa2d5061ab7b'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '공시체', '강도시험용 표준 시험체. 원주형(지름:높이=1:2)이 표준. ※치수 규격 확인.', '["채취 빈도·양생 방법(표준양생 vs 현장양생)에 따라 판정 용도가 다름."]'::jsonb, true),
  ('45c01822-3039-5c39-9b15-a35389465515'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 강도', '재령', '타설 후 경과 일수. 강도는 재령에 따라 증가 — 28일이 판정 표준, 초기 재령 강도로 거푸집 해체 판단.', '[]'::jsonb, false),
  ('13b0372b-405d-5922-8e9f-f3a9b11c4a2c'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 변형성질', '탄성계수 (콘크리트)', '응력-변형률 관계의 기울기. 압축강도가 클수록, 단위질량이 클수록 큼.', '[]'::jsonb, false),
  ('118d4f13-57cd-543c-9cb6-655602967a5f'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 변형성질', '포아송비', '축방향 압축 시 가로 방향 팽창 변형률의 비. 콘크리트는 대략 1/6~1/8(0.13~0.17) 수준.', '[]'::jsonb, false),
  ('a5e2c1aa-6fc4-5a58-b0f8-2b567f728c5b'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 변형성질', '크리프', '지속하중 아래에서 시간이 지나며 변형이 계속 증가하는 현상.', '["커지는 조건: W/C 클수록, 재하 재령 어릴수록, 응력 클수록, 부재 얇을수록, 습도 낮을수록.", "결과: 장기 처짐 증가, PS 강재의 프리스트레스 손실."]'::jsonb, false),
  ('f969605b-81aa-596e-9b36-6b17f5c5db91'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 변형성질', '건조수축', '수분 증발로 콘크리트 부피가 줄어드는 현상(하중과 무관).', '["단위수량이 클수록 큼 — 수축 균열의 주범. 대책: 단위수량↓, 팽창재, 수축이음.", "비교·암기 — 크리프(하중 탓, 시간) ↔ 건조수축(수분 탓, 시간) — 장기변형 두 축."]'::jsonb, false),
  ('396e91e3-54b7-5c3a-b3d0-0f6a7df6ffa6'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 변형성질', '자기수축', '외부 건조 없이 수화반응 자체의 물 소비로 생기는 수축. W/B가 낮은 고강도 콘크리트에서 두드러짐.', '[]'::jsonb, false),
  ('9e67d72b-7e4a-5c7e-a4f0-5ba483c9b76d'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '수밀성', '물의 침투·투과에 저항하는 성질. W/C 낮게, 밀실 다짐, 충분한 양생이 3대 원칙.', '[]'::jsonb, false),
  ('2e06a042-b6f5-53db-b8e0-3f07a8093c7c'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '내구성', '환경 작용(중성화·염해·동해·화학침식 등)에 저항해 성능을 유지하는 성질. 열화 원인별 대책이 면접 단골.', '[]'::jsonb, false),
  ('24d1b467-a06f-55ac-be10-dedee3c32ad0'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '중성화 (탄산화)', 'CO2가 수산화칼슘과 반응해 콘크리트의 강알칼리(pH 12~13)를 잃게 하는 현상.', '["알칼리가 철근 부동태막을 지키는데, 중성화 도달 시 부식 개시 → 녹 팽창 → 피복 균열·박락.", "속도: W/C 클수록·피복 얇을수록·실내 CO2 농도 높을수록 빠름."]'::jsonb, false),
  ('f52bdbed-1ca4-5af6-a4c6-789015eb8669'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '염해', '염소이온이 부동태피막을 파괴해 철근을 부식시키는 열화. 해사·해안 비래염분·제설제가 원인.', '["대책: 염화물 총량 규제, 피복 확보, W/C↓, 방청제, 에폭시 도막 철근."]'::jsonb, false),
  ('3fc2cc8a-ca8b-5e58-b13f-0263ed99fde9'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '동결융해', '콘크리트 속 수분이 얼고 녹기를 반복하며 조직이 붕괴되는 열화(표면 스케일링·팝아웃).', '["최고의 대책: AE제로 연행공기 확보(기포가 동결 팽창압의 완충 공간)."]'::jsonb, false),
  ('c33bf268-1b62-545e-bafe-1fc862a567e6'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '화학적 침식', '산·황산염·하수 가스 등이 시멘트 수화물을 분해·팽창시키는 열화. 내황산염시멘트·표면 보호로 대응.', '[]'::jsonb, false),
  ('35b08238-be76-56ec-847e-aea69713194a'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '철근 부식', '부식 생성물(녹)의 부피 팽창(2~6배)이 피복을 밀어 균열·박락을 일으키는 열화의 최종 단계.', '["비교·암기 — 중성화·염해는 ''문을 여는 원인'', 부식·팽창은 ''집을 부수는 결과'' — 인과로 연결 설명."]'::jsonb, false),
  ('5aa733b4-ff8c-5e7a-83dc-820120b89f0d'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '폭렬현상', '화재 고온에서 콘크리트 내 수증기압이 급상승해 표면이 폭발적으로 박리되는 현상, 고강도(치밀)일수록 취약.', '["대책: 폴리프로필렌 섬유 혼입(녹아서 증기 통로 형성), 내화 피복."]'::jsonb, false),
  ('f1da071d-5ffd-522f-a464-820776ad2c77'::uuid, '2장 · I 콘크리트재료 · 6절 · 굳은콘크리트성질 · 내구성', '페놀프탈레인 시험', '파단면에 시약을 뿌려 중성화 깊이를 재는 시험 — 붉게 변하면 알칼리 건전, 무색이면 중성화된 부분.', '[]'::jsonb, false),
  ('683a08d6-d5bb-5351-b362-c88f5167d2db'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 표면시공결함', '허니콤 (곰보)', '모르타르가 굵은골재 사이를 채우지 못해 표면·내부가 벌집처럼 빈 결함.', '["원인: 다짐 부족, 재료분리, 된 반죽, 철근 과밀, 거푸집 틈 누출. 방지: 충분한 다짐·적정 슬럼프·낙하높이 제한.", "보수: 취약부 제거 후 폴리머 모르타르 충전 등."]'::jsonb, false),
  ('b9331537-c3b9-5ee7-a598-ac6518e90bd4'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 표면시공결함', '콜드조인트', '먼저 친 콘크리트가 응결된 뒤 이어쳐 일체화되지 못한 계획 외 이음.', '["원인: 타설 지연·순서 착오. 방지: 연속 타설 계획, 지연제, 이어치기 허용시간 관리. ※시간 확인.", "비교·암기 — 시공이음(계획된 이음, 정상) ↔ 콜드조인트(계획 외, 하자) — 반드시 짝으로 답할 것."]'::jsonb, true),
  ('6ea54595-924f-518c-b13c-013c5923016b'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 표면시공결함', '표면기포', '거푸집면에 공기·물이 갇혀 생긴 작은 구멍(곰보보다 얕음). 다짐·박리제 과다·타설속도의 문제.', '[]'::jsonb, false),
  ('a0f309c9-7453-51a3-84f9-2c877487e3b0'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 표면시공결함', '모래줄무늬 (샌드스트리크)', '블리딩수가 거푸집면을 타고 오르며 모래만 남긴 줄무늬. 블리딩 과다의 흔적.', '[]'::jsonb, false),
  ('6f070f47-62c1-5b36-b46d-765cd199dcfd'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 표면시공결함', '백화 (콘크리트)', '가용 성분이 수분과 함께 표면으로 나와 CO2와 반응, 흰 탄산칼슘으로 석출되는 현상. 수분 이동 차단이 근본 대책.', '[]'::jsonb, false),
  ('eeca9557-6336-5725-9e18-c88789dd36e5'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '소성수축균열', '굳기 전(소성 상태) 표면 수분이 증발 속도를 못 따라가 생기는 얕고 불규칙한 균열.', '["바람 불고 건조한 날 슬래브 표면에 발생 — 대책: 초기 표면 보호(피막·시트), 바람막이."]'::jsonb, false),
  ('46fe19ab-85d1-5092-882a-594a89d3899b'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '건조수축균열', '경화 후 수분 증발 수축이 구속되어 생기는 균열. 개구부 모서리·단면 변화부에 발생.', '[]'::jsonb, false),
  ('b7ff9e3a-53ff-5f0e-8fbe-c64a66e43ff5'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '침하균열', '블리딩으로 콘크리트가 가라앉을 때 상부 철근이 붙잡아 철근 위를 따라 생기는 균열.', '["대책: 블리딩 저감, 타설 속도 조절, 태핑(재다짐)."]'::jsonb, false),
  ('069ed02f-1d8b-58d0-8c1f-1324e0511494'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '온도균열', '매스콘크리트의 수화열로 내외부 온도차·냉각 수축이 구속되어 생기는 균열.', '["대책: 저발열 배합, 프리쿨링·파이프쿨링, 분할 타설, 보온(내외부 온도차 축소)."]'::jsonb, false),
  ('28af5e01-e79a-548d-bf29-9432ff8e64d7'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '망상균열', '표면에 그물처럼 퍼진 미세 균열. 표면 급건조·양생 불량·중성화 진행 표면 등에서 발생.', '[]'::jsonb, false),
  ('0f7597cc-c10f-59d1-bc65-2df6088547d5'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '박리 · 박락', '표면 콘크리트가 떨어지는 현상. 철근 부식 팽창·동해·시공 불량이 원인 — 낙하 위험으로 안전 이슈.', '[]'::jsonb, false),
  ('63779451-1a58-596d-82b9-50e86b0c05ba'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 균열시기원인별', '들뜸', '마감층·표층이 바탕에서 분리되어 뜬 상태. 두들김 검사로 확인.', '[]'::jsonb, false),
  ('8b510d87-51bb-5881-bce7-1620ec20cb23'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '비파괴시험 (NDT)', '구조물을 부수지 않고 강도·내부 결함을 추정하는 시험의 총칭. 기존 구조물 진단의 기본.', '[]'::jsonb, false),
  ('d9dc99a7-a17b-52e1-93ce-d84633fab279'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '슈미트해머 (반발경도법)', '해머 타격의 반발 정도로 표면 경도 → 압축강도를 추정. 간편하지만 표면 상태 영향 큼(보정 필요).', '[]'::jsonb, false),
  ('444c3afb-03d7-51f5-adea-caf2888903fe'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '초음파법', '초음파 전파 속도로 강도·내부 공극·균열 깊이를 추정. 속도 빠르면 밀실.', '[]'::jsonb, false),
  ('f44338e3-487c-5af3-bb7d-1e20c580b472'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '복합법', '반발경도법+초음파를 병용해 추정 신뢰도를 높이는 방법.', '[]'::jsonb, false),
  ('3e8cb71a-0f1f-5706-8338-13138b251234'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '자기법 (철근탐사)', '전자기로 철근 위치·피복두께·직경을 탐사. 코어 채취 전 철근 피해서 뚫기 위해서도 사용.', '[]'::jsonb, false),
  ('64fc64c5-7857-5801-8062-f874d2f2e60d'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '코어채취 시험', '구조체에서 원주형 코어를 뚫어 직접 압축시험. 실측 강도의 기준이나 구조체 손상 — 위치·수량 신중.', '["비교·암기 — ''간편 추정(슈미트) → 정밀 추정(초음파·복합) → 직접 확인(코어)'' — 신뢰도 사다리로 기억."]'::jsonb, false),
  ('418fb3f0-7bbb-5929-bd4a-06c93fcf0ae8'::uuid, '2장 · I 콘크리트재료 · 7절 · 콘크리트결함시험 · 비파괴강도시험', '받아들이기 검사', '레미콘 현장 도착 시 슬럼프·공기량·염화물·온도 확인 후 타설 승인하는 검사. 공시체 제작 포함.', '["''현장에서 레미콘 오면 뭘 확인하나'' — 신입 면접 단골 실무 질문."]'::jsonb, false),
  ('a8cc460b-7ccd-5fb7-a762-abffc19a56ce'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '거푸집', '굳지 않은 콘크리트를 소정 형상으로 유지하고 경화까지 보호하는 가설 틀(폼+지지재).', '["요구조건: 형상 정확·수밀·강성·조립해체 용이·전용성(재사용)."]'::jsonb, false),
  ('6fe56aad-c268-5a1a-a7be-8a7dafd64bd3'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '거푸집널 · 장선 · 멍에', '거푸집널(콘크리트에 접하는 판) → 장선(널을 받침) → 멍에(장선을 받침) → 동바리 순으로 하중 전달.', '["비교·암기 — ''널-장선-멍에-동바리'' 하중 흐름 한 줄이 거푸집 구조의 뼈대."]'::jsonb, false),
  ('f99c9ffd-dbee-5d50-a0c4-5f1bff9ea60b'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '긴결재', '거푸집 양면을 묶어 측압에 벌어지지 않게 하는 부속의 총칭(폼타이 등).', '[]'::jsonb, false),
  ('dcf27f5f-cc14-5651-885e-2a061d7f5f77'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '폼타이', '벽 거푸집 양쪽 널을 관통·긴결하는 볼트. 측압으로 벌어짐 방지.', '[]'::jsonb, false),
  ('4a3a21e0-8384-5595-bba6-eb712cdef600'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '세퍼레이터', '양쪽 거푸집널의 간격(벽두께)을 일정하게 유지하는 격리재.', '["비교·암기 — 폼타이(벌어짐 방지=당김) ↔ 세퍼레이터(좁아짐 방지=버팀) — 방향 반대 짝으로 출제."]'::jsonb, false),
  ('60f01e51-9ec3-50c6-9845-d31e5a3cc488'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '스페이서 (거푸집)', '간격 유지 부속의 총칭 — 문맥상 철근 피복용 스페이서와 구분할 것.', '[]'::jsonb, false),
  ('2352bcef-8012-578a-bb2a-74f992ec36bc'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집의구성', '박리제', '거푸집널 표면에 발라 콘크리트와의 부착을 막고 탈형을 쉽게 하는 도포제. 철근에 묻지 않게 주의.', '[]'::jsonb, false),
  ('63c1f018-e2db-599a-8754-7628d1cb2de9'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '유로폼', '합판+강재 프레임의 규격화 패널 거푸집. 인력 조립의 국내 표준 재래 공법.', '[]'::jsonb, false),
  ('ce8f9432-8590-5e15-8a58-b0ed084a84eb'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '알루미늄폼 (알폼)', '알루미늄 합금 거푸집. 경량·고전용(수백 회)·수직도 우수, 표면 평활(견출 감소) — 아파트 골조 표준.', '["초기 투자비 큼, 해체 소음, 콘크리트 표면 기포 관리."]'::jsonb, false),
  ('1b5075ef-801e-5bf5-96c2-652d8d77cbff'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '갱폼', '외벽용 대형 일체형 강재 거푸집. 크레인으로 한 층씩 인양·반복 사용, 외부 발판 일체.', '["인양 중 낙하·추락 사고 다발 — 고정볼트 해체 순서·인양 절차 관리가 핵심 안전 포인트."]'::jsonb, false),
  ('61f22196-7982-5511-8072-6cb065ae6e41'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '클라이밍폼 (ACS·RCS)', '유압 등으로 스스로 상승(셀프클라이밍)하는 대형 시스템폼. 크레인 없이 인상 — 초고층 코어월 표준.', '["비교·암기 — 갱폼(크레인 인양) ↔ 클라이밍폼(유압 자력 상승) — 인양 방식으로 구분."]'::jsonb, false),
  ('51efe3fa-5b1b-5f97-80dd-d4c3f918fc31'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '슬립폼', '거푸집을 연속으로 서서히 끌어올리며 쉬지 않고 타설하는 공법. 사일로·굴뚝·교각 등 단면 일정 구조물.', '["이음 없는 일체 구조물 — 24시간 연속 작업이 전제."]'::jsonb, false),
  ('e27e6521-cbc8-5a36-a2ad-fd6320e85670'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '슬라이딩폼', '슬립폼과 같은 계열의 연속 상승 거푸집(용어 혼용). 수직 활동 거푸집으로 묶어 이해.', '[]'::jsonb, false),
  ('e149c328-882c-5c30-9a9f-eeee8770b15b'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '터널폼', '벽+슬래브를 ㄱ자(트윈 ㄷ자) 일체로 타설하는 강재 거푸집. 벽식 아파트·호텔 등 반복 평면에 유리.', '[]'::jsonb, false),
  ('63b2cf3c-22c4-5da0-ba28-f0f3a57e2f58'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '트래블링폼', '수평으로 이동(레일 주행)하며 반복 타설하는 대형 거푸집. 터널 라이닝·긴 구조물용.', '[]'::jsonb, false),
  ('aa8b3522-562f-5ed2-bd26-aae7f94bd132'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '와플폼', '격자 리브 슬래브(와플 슬래브)를 만드는 요철 상자형 거푸집. 장스팬 무보 슬래브에 사용.', '[]'::jsonb, false),
  ('ed487008-7fbd-5dbf-921f-414749813cdc'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 거푸집공법의종류', '데크플레이트', '골 있는 강판을 슬래브 바닥 거푸집 겸 구조재로 쓰는 것. 동바리 절감·공기 단축 — 철골조 표준.', '["거푸집 전용(제거식)과 구조 합성용(합성데크)으로 구분."]'::jsonb, false),
  ('e757ba37-a094-5abb-b365-a1b0cf9ec298'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '무지주공법', '동바리 없이 보빔·페코빔 등 수평지지보로 슬래브 거푸집을 받치는 공법. 하부 공간 활용·층고 큰 곳 유리.', '[]'::jsonb, false),
  ('bfdc562f-fb95-5ede-8cdf-1f4a62785acd'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '보빔 · 페코빔', '간격 조절이 가능한 신축형 수평 지지보. 무지주공법의 핵심 부재.', '[]'::jsonb, false),
  ('9313e45c-629d-527a-9e6a-f084a4faa6d3'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '측압 (콘크리트)', '굳지 않은 콘크리트가 거푸집 옆면을 미는 압력.', '["커지는 조건: 타설속도 빠를수록, 온도 낮을수록, 슬럼프 클수록, 다짐 많을수록, 부재 높을수록(헤드까지).", "벽·기둥 거푸집 붕괴(터짐)의 원인 — 설계 시 최대측압 검토."]'::jsonb, false),
  ('5beb7bf8-1afe-5cda-aa2b-e3f9bf538f67'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '콘크리트헤드', '타설 윗면에서 최대측압이 생기는 지점까지의 깊이. 그 이하로는 측압이 더 커지지 않음(응결 시작).', '["비교·암기 — ''측압은 헤드까지 커지다 멈춘다'' — 측압 그래프의 꺾임으로 기억."]'::jsonb, false),
  ('2a10f1d0-156e-559b-8331-790b81e6dbfa'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '거푸집 존치기간', '해체 가능 시기까지 거푸집·동바리를 유지하는 기간. 부재(수직/수평)·시멘트 종류·평균기온·강도로 결정. ※표 확인.', '["수직재(벽·기둥)는 압축강도 기준 도달 시, 수평재(슬래브·보 밑)는 설계강도 대비 비율+동바리 존치 — 조기 해체가 붕괴·처짐·균열의 원인."]'::jsonb, true),
  ('9ba7674c-8f1c-530a-a344-71c73e4bf54f'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '필러서포트 (동바리 바꾸어세우기)', '슬래브 거푸집 해체 시 일부 동바리(필러)를 남기거나 재설치해 하중을 계속 받게 하는 조치.', '["원칙적으로 ''바꾸어세우기''는 금지·최소화, 남겨두기(필러 존치)로 계획. ※규정 확인."]'::jsonb, true),
  ('391501d8-bbb1-5dd2-b553-34fb6f603a96'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '거푸집 · 동바리 구조검토', '타설 전 연직하중(고정+작업)·측압·풍하중에 대한 구조 안전성 계산과 조립도 작성.', '["일정 규모 이상은 관계전문가 확인 의무 — 가설 붕괴 사고 예방의 제도적 장치. ※대상 기준 확인."]'::jsonb, true),
  ('552428b8-c1d9-51be-80cc-171e4ae8ca54'::uuid, '2장 · II 거푸집철근타설 · 1절 · 거푸집공사 · 설계관리포인트', '거푸집 검사', '타설 전 치수·수직도·청소 상태·박리제·긴결 상태·매설물 위치를 확인하는 검사(타설 승인 전 필수).', '[]'::jsonb, false),
  ('491fd9a8-b707-59c0-9cf8-ae404e388205'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 철근의종류규격', '이형철근 · 원형철근', '이형철근: 표면에 리브·마디가 있어 부착력 우수(현재 표준, D 표기). 원형철근: 매끈한 환봉(현재 구조용 거의 미사용).', '[]'::jsonb, false),
  ('3c4cfaa4-54e9-50dc-84a2-ac829f815c36'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 철근의종류규격', '철근 항복강도 (SD 표기)', 'SD400 = 항복강도 400MPa 이형철근. 숫자가 항복강도.', '["고강도 철근(SD500·600) 사용 확대 — 철근량 절감, 이음·정착 관리가 더 중요해짐."]'::jsonb, false),
  ('48f0dbe3-1c63-5208-b198-520c99699438'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 가공', '철근 가공', '도면(가공도)대로 절단·구부림 하는 작업. 원칙적으로 상온 가공(열을 가하면 강도 저하 우려).', '[]'::jsonb, false),
  ('446345a3-f279-545e-8bbc-e4b48269dbf2'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 가공', '표준갈고리', '정착력 확보를 위해 철근 끝을 구부리는 표준 형태(180°·135°·90°).', '["스터럽·띠철근의 135° 갈고리는 내진 성능(벌어짐 방지)과 직결. ※연장 길이 확인."]'::jsonb, true),
  ('01885293-9add-59bc-9c71-fec6d6926364'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 가공', '구부림 최소내면반지름', '구부릴 때 철근이 손상되지 않도록 규정한 최소 곡률 반지름(지름의 배수). ※배수 확인.', '[]'::jsonb, true),
  ('0674b887-6574-5f6b-ae63-96a208d1dbb4'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 이음4가지방법', '겹침이음', '두 철근을 일정 길이 겹쳐 콘크리트 부착으로 힘을 전달하는 가장 보편적 이음. ※이음길이 산정 확인.', '["원칙: 응력 큰 곳 회피, 한 단면 집중 회피(엇갈림 배치), 굵은 철근(D35 초과)은 겹침이음 금지. ※확인."]'::jsonb, true),
  ('c883ca9e-6f25-5df5-baef-6b3607798a48'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 이음4가지방법', '가스압접', '철근 단부를 가스 불꽃으로 가열·가압해 부풀려 접합하는 이음.', '["검사: 외관(부풀음 직경·길이·편심) + 초음파·인장시험. 압접공 자격 필요."]'::jsonb, false),
  ('b258c7be-576e-5c43-b117-15db88a7bb74'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 이음4가지방법', '기계식이음 (커플러)', '나사형 커플러 등 기계 장치로 잇는 이음. 품질 균일·검사 용이 — 굵은 철근·PC 접합에 확대.', '[]'::jsonb, false),
  ('dd1ff680-7427-50f8-90e2-6dbd918360cc'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 이음4가지방법', '용접이음 (철근)', '철근을 직접 용접하는 이음. 용접성 확보(철근 재질)와 품질관리가 까다로워 제한적.', '["비교·암기 — 이음 4형제: 겹침(부착으로) / 압접(불로) / 커플러(기계로) / 용접(녹여서)."]'::jsonb, false),
  ('8e055bc7-896e-50ed-82bb-3fc0288a2d39'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 정착부착피복', '정착 · 정착길이', '철근이 뽑히지 않도록 콘크리트에 묻어 넣는 것과 그 필요 길이.', '["인장 정착길이는 철근 강도↑·지름↑일수록 길고, 콘크리트 강도↑일수록 짧음. ※산정식 확인."]'::jsonb, true),
  ('1df66e49-8244-50b6-a4f8-1824804d0576'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 정착부착피복', '부착 (철근)', '철근 표면과 콘크리트 사이 힘 전달 작용. RC가 일체로 거동하는 근본 전제(마디의 기계적 맞물림이 주역).', '[]'::jsonb, false),
  ('1d4e1428-2b0a-5ca4-8e51-da5ce5115a07'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 정착부착피복', '피복두께', '철근 표면에서 콘크리트 표면까지의 최단 거리.', '["역할 3가지: 1)철근 부식 방지(중성화 도달 지연) 2)내화(열 차단) 3)부착력 확보.", "부위·환경(흙에 접함/옥외/옥내)별 최소값 규정. ※수치 표 확인 — 면접 최다 출제 항목."]'::jsonb, true),
  ('80311f4a-b332-5f44-aa5d-adcfd35d4568'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 정착부착피복', '스페이서 · 간격재 (철근)', '철근과 거푸집 사이 간격(피복)을 유지하는 받침(모르타르·플라스틱·강재). 배근검사 확인 항목.', '[]'::jsonb, false),
  ('8afdd94b-ab5f-5620-bd9d-291dbdff3d13'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 정착부착피복', '결속선', '교차 철근을 묶는 연강 철선. 구조 접합이 아니라 위치 고정용.', '[]'::jsonb, false),
  ('e02508c7-2dbe-5ef9-8397-a2c1c12eb703'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '주근 · 배력근', '주근: 주된 응력(휨·인장)을 받는 철근. 배력근: 주근과 직각으로 응력 분산·간격 유지·수축 대응.', '["1방향 슬래브: 단변 방향이 주근, 장변 방향이 배력근."]'::jsonb, false),
  ('e1a556f9-8eef-5669-adf6-3642b55d37cb'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '늑근 (스터럽)', '보의 전단 보강 철근. 주근을 감싸 전단 균열(45° 사인장)을 제어.', '["전단력이 큰 단부에서 촘촘하게 배치."]'::jsonb, false),
  ('f32bd7c3-4f92-5392-b868-173bb3dd2d63'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '띠철근 (후프)', '기둥 주근을 둘러 감는 수평 철근. 주근 좌굴 방지 + 심부 구속 + 전단 보강.', '["비교·암기 — 늑근(보의 전단) ↔ 띠철근(기둥의 구속) — 부재만 다르지 ''감싸는 역할''은 동일 계열."]'::jsonb, false),
  ('2b585c51-fdde-57f2-bbbb-2b1e52fceec0'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '나선철근', '기둥 주근을 나선형으로 연속으로 감는 철근. 띠철근보다 구속 효과 우수(연성↑).', '[]'::jsonb, false),
  ('a6141f0a-ef4c-55ce-9103-0da81d35c0c6'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '벤트근', '보에서 휨모멘트 분포에 맞춰 구부려 올린 철근(굽힘철근). 단부 상부 인장에 대응.', '[]'::jsonb, false),
  ('fa8cdd30-1639-5887-a8fa-c06aae17d970'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '상부근 · 하부근', '보·슬래브의 위·아래 철근. 연속보 기준 중앙부는 하부(정모멘트 인장), 단부(지점부)는 상부(부모멘트 인장)가 주 인장.', '["비교·암기 — ''중앙은 아래가 당겨지고, 지점은 위가 당겨진다'' — 배근의 제1원리. 휨모멘트도와 함께 그려 암기."]'::jsonb, false),
  ('5e462d51-3a09-55c1-ba01-b0933a2681e3'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '온도철근', '온도·수축 균열 분산을 위해 배치하는 최소 철근(1방향 슬래브의 장변 방향 등).', '[]'::jsonb, false),
  ('c1b365aa-d048-56c1-b6f3-84c9314faf2a'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '개구부 보강근', '슬래브·벽 개구부 주위 응력 집중에 대비해 주변·모서리(경사근)에 더 넣는 보강 철근.', '[]'::jsonb, false),
  ('27fa54b1-0c1d-572b-b580-2cabac6c6c1b'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '철근 프리패브', '철근을 공장·지상에서 조립(선조립)해 양중 설치하는 공법. 품질·공기·고소작업 감소에 유리.', '[]'::jsonb, false),
  ('fbaf4d1d-0234-567d-b7f5-10e48a42787f'::uuid, '2장 · II 거푸집철근타설 · 2절 · 철근공사 · 배근부위별명칭', '배근검사', '타설 전 철근 지름·개수·간격·이음·정착·피복(스페이서)을 도면과 대조하는 검사. 감리 입회 필수.', '["타설 후에는 확인 불가 — ''묻히기 전 마지막 관문''이라는 논리로 중요성 설명."]'::jsonb, false),
  ('e9a0e1dc-e830-5007-bf53-5592d6cd0167'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 운반', '레미콘 (레디믹스트 콘크리트)', '공장에서 비벼 트럭믹서로 현장에 공급하는 콘크리트. 현대 콘크리트 공사의 표준 공급 방식.', '[]'::jsonb, false),
  ('d1adb0b6-4165-51f9-a21c-96cdb12695c9'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 운반', '운반시간 한도', '비비기 시작부터 타설 완료까지의 허용 시간(외기온에 따라 다름). 초과 시 슬럼프 저하·콜드조인트 위험. ※시간 확인.', '[]'::jsonb, true),
  ('63f54f28-fee8-51c2-955b-fc3e0955efa6'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 운반', '펌프카 압송', '붐+배관으로 콘크리트를 압송 타설하는 표준 장비. 압송성(펌퍼빌리티) 확보와 배관 막힘 관리.', '[]'::jsonb, false),
  ('c860c130-d68c-5897-954c-a6c8b0bb2d0e'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 운반', 'CPB (콘크리트분배기)', '고층 코어 등에서 배관 끝에 설치해 붐으로 타설 위치를 분배하는 장비. 초고층 타설의 필수 장비.', '[]'::jsonb, false),
  ('7b9051b8-62c8-51f2-b528-6e47137c473f'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 타설', '타설', '콘크리트를 거푸집에 부어 넣는 작업.', '["원칙: 낮은 곳부터, 수직 낙하, 한 곳 집중 금지(횡류 이동 금지 — 재료분리), 연속 타설."]'::jsonb, false),
  ('59965ad9-5c62-5bfc-af97-1495b444ee83'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 타설', '자유낙하높이', '재료분리를 막기 위한 낙하 높이 제한. 초과 시 슈트·타설관 사용. ※제한값 확인.', '[]'::jsonb, true),
  ('8d320381-c4e9-593e-b7d7-ec8478f4d88a'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 타설', '타설속도 · 타설순서', '측압·침하균열·콜드조인트를 좌우, 계획서(타설계획도)로 구획·순서·속도를 사전 결정.', '[]'::jsonb, false),
  ('6ae226ff-d576-57fe-8949-15cb8bc07be2'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 타설', 'VH 분리타설', '수직부재(기둥·벽) 먼저, 침하 안정 후 수평부재(보·슬래브) 타설. 침하 차이로 인한 접합부 균열 방지.', '[]'::jsonb, false),
  ('39b29670-3ba0-5f8f-9d4b-6e4a216108bb'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '이어치기 시간한도', '먼저 친 콘크리트가 굳기 전에 이어쳐야 하는 허용 시간(외기온별). 초과 시 콜드조인트. ※시간 확인.', '[]'::jsonb, true),
  ('f9c3ef17-17b2-50de-8cfa-eb0040a7aeaf'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '시공이음', '시공 사정상 계획적으로 두는 이음. 전단력이 작은 위치에, 부재 축 직각으로.', '["처리: 레이턴스 제거 → 습윤 → (시멘트풀) → 신 콘크리트 밀실 다짐."]'::jsonb, false),
  ('f564f75d-eafb-5741-8152-59f446668a5f'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '신축이음 (익스팬션조인트)', '온도 변화·부등침하에 대응해 구조체를 완전히 분리하는 이음(철근도 절단, 줄눈재 충전).', '["긴 건물·평면 꺾임부·증축 접합부에 설치."]'::jsonb, false),
  ('9371d5dc-88f9-59a4-8af8-583214ec044b'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '수축이음 (컨트롤조인트)', '단면을 일부러 얇게 만들어 수축 균열을 그 자리로 유도하는 이음(균열유발줄눈).', '["비교·암기 — 조인트 3종 정리: 시공이음(작업 편의) / 신축이음(움직임 흡수·완전 분리) / 수축이음(균열 유도·단면 감소)."]'::jsonb, false),
  ('813f9cd8-daf6-5e2c-9cc8-d339c89ec271'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '딜레이조인트', '긴 구조물에서 일정 구간을 남겨두고 나중에 타설해 초기 수축을 흡수시키는 지연 이음(포어 스트립).', '[]'::jsonb, false),
  ('c1fa0da6-e7cc-5f4a-bcb0-4d54aa3a8e81'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 이음조인트', '지수판', '이음부를 관통하는 물길을 막기 위해 이음 속에 묻는 차수 판재(PVC·수팽창 고무 등). 지하 외벽 시공이음 필수.', '[]'::jsonb, false),
  ('23ac8055-4094-54a5-aa3d-ea8d54fc79b3'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 다짐', '다짐 · 진동기', '봉형 진동기로 공극·갇힌공기를 빼 밀실화하는 작업. 곰보 방지의 핵심 공정.', '[]'::jsonb, false),
  ('a7938c4d-13db-5fc7-b6df-2bbafe6639d0'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 다짐', '진동기 사용법', '수직 삽입, 아래층에 일부(10cm 정도) 관입, 간격 일정(유효반경 내), 구멍이 메워질 때까지 서서히 인발.', '["과다 진동은 재료분리 — ''모자라도 곰보, 지나쳐도 분리''. ※삽입 간격·시간 확인."]'::jsonb, true),
  ('ccadce6e-62d3-5433-ae75-0a89146fe250'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '습윤양생', '표면을 젖은 상태로 유지(살수·양생포·담수)하는 표준 양생. 수화에 물이 계속 필요하다는 원리.', '[]'::jsonb, false),
  ('09bdbeaf-6d58-547c-af2c-2e77031059d9'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '증기양생', '고온 증기로 강도 발현을 촉진. PC 공장 제품의 표준(당일 탈형 가능).', '[]'::jsonb, false),
  ('abe36c8f-7751-5727-8a80-ec6d771d44a1'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '피막양생', '양생제를 뿌려 수분 증발을 막는 막을 형성. 살수가 어려운 넓은 슬래브·포장에 사용.', '[]'::jsonb, false),
  ('3cf2706e-c55f-55f4-8063-13e6fe291037'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '전기양생 · 가열양생', '전열·온풍 등으로 가열해 한중에 온도를 확보하는 양생.', '[]'::jsonb, false),
  ('202312f6-9e4b-51ab-9e50-ec9a996bbc90'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '단열보온양생', '시트·단열재로 덮어 수화열을 가두어 온도를 유지하는 한중 양생의 기본.', '[]'::jsonb, false),
  ('965f6019-7e05-535d-884b-2c1ca56caa84'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '양생기간과 온도', '일평균기온·시멘트 종류에 따른 최소 습윤양생 기간 규정. 초기 동해 방지·임계강도 확보가 한중의 핵심. ※일수·강도값 확인.', '[]'::jsonb, true),
  ('954930ef-5442-5ced-bc22-525441f9de16'::uuid, '2장 · II 거푸집철근타설 · 3절 · 콘크리트타설양생 · 양생', '표면마무리 · 쇠흙손질', '타설면을 고르고 다지는 마감. 블리딩수 처리 후 시기 맞춰 흙손질(너무 이르면 백태·너무 늦으면 불가).', '[]'::jsonb, false),
  ('a2ad157f-5f82-5fdf-8871-fea2dbe45243'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 기후대응', '한중콘크리트', '일평균기온 4℃ 이하 조건에서 초기 동해를 막도록 관리하는 콘크리트. ※적용 온도 확인.', '["관리: W/C 낮게, AE 콘크리트 필수, 가열 재료(물·골재), 보온·가열 양생, 초기 압축강도(임계강도) 확보. ※강도값 확인."]'::jsonb, true),
  ('35b25c29-da30-573c-b5fa-f111120cc7a0'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 기후대응', '서중콘크리트', '일평균기온 25℃ 초과 조건의 콘크리트. ※적용 온도 확인.', '["문제: 슬럼프 급저하·응결 빠름·콜드조인트·소성수축균열. 관리: 저온 재료·지연제·신속 타설·야간 타설·양생수 살포.", "비교·암기 — 한중(얼지 않게 데워라) ↔ 서중(마르지 않게 식혀라) — 대칭 짝."]'::jsonb, true),
  ('8a9ee196-3e01-5713-abd2-0d9156e749bc'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '매스콘크리트', '단면이 커 수화열 온도균열이 문제 되는 콘크리트(대략 벽 0.5m·슬래브 0.8m 이상 등). ※기준 확인.', '["대책 3단계: 재료(저발열시멘트·혼화재) → 배합(단위시멘트량↓) → 시공(프리쿨링·파이프쿨링·분할타설·보온)."]'::jsonb, true),
  ('31322229-37f8-5780-8073-67f4cb498b9b'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '수화열 관리', '내외부 온도차(대략 25℃ 이내 관리 통용 ※확인)와 냉각 속도를 관리해 온도균열지수를 확보하는 활동.', '[]'::jsonb, true),
  ('643f1630-0b86-5fc8-83c5-86a3c39d45bc'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '파이프쿨링', '부재 속에 관을 묻고 냉수를 순환시켜 내부 온도를 낮추는 사후 냉각.', '["비교·암기 — 프리(치기 전 재료를 차게) ↔ 파이프(친 후 속을 식힘) — 시점으로 구분."]'::jsonb, false),
  ('b1ff3da1-34fb-5c01-8e36-b3ec19e00c42'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '프리쿨링', '재료(물·골재)를 미리 냉각(얼음물·액체질소)해 타설 온도 자체를 낮추는 사전 냉각.', '[]'::jsonb, false),
  ('e0115277-3048-51a7-8e95-ad241d12d510'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '고강도콘크리트', '설계기준강도가 높은 콘크리트(보통 40MPa 이상 통용 ※기준 확인). 실리카퓸+고성능감수제로 실현.', '["낮은 W/B → 자기수축·폭렬 취약 — 화재 시 폭렬 대책 필요."]'::jsonb, true),
  ('fbc11209-abd8-5003-9069-61025340e51a'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '고성능콘크리트', '고강도+고유동+고내구를 종합한 콘크리트의 총칭.', '[]'::jsonb, false),
  ('9d1d92d4-8400-5fa2-9fb4-11162a00a50e'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '고유동콘크리트', '다짐을 거의 안 해도 채워지는 높은 유동성의 콘크리트. 슬럼프플로로 관리.', '[]'::jsonb, false),
  ('88d469b6-0c30-5133-a7f6-8834d33f7c9b'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '자기충전콘크리트 (SCC)', '진동다짐 없이 자중만으로 철근 사이를 채우는 콘크리트.', '["과밀 배근·복잡 형상·소음 민원 현장에 유리. 재료분리 저항성(점성) 확보가 관건."]'::jsonb, false),
  ('ec5b0473-2cc9-5c43-9d50-6fd1b190d5be'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '섬유보강콘크리트', '강·유리·합성 섬유를 혼입해 인장·균열·인성(충격)을 개선한 콘크리트. 숏크리트·바닥판 등.', '[]'::jsonb, false),
  ('064df983-323c-53e3-baf8-79481155065b'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '경량콘크리트', '경량골재·기포로 자중을 줄인 콘크리트. 구조 경량화·단열, 강도·탄성계수는 낮아짐.', '[]'::jsonb, false),
  ('1a0a077f-dce7-56aa-957b-be0c2387dc1c'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '중량콘크리트 (차폐용)', '중량골재로 밀도를 높여 방사선을 차폐하는 콘크리트. 원자력·의료시설.', '[]'::jsonb, false),
  ('1104205a-1054-5c0c-8101-e20d77f3e472'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 단면성능별', '수밀콘크리트', '물탱크·지하 외벽 등 수밀성을 특히 요구하는 콘크리트. W/C 낮게(50% 이하 통용 ※확인), 밀실 다짐, 이음 최소화·지수판.', '[]'::jsonb, true),
  ('21b1d3b8-e2fb-5d27-a733-0b95b26b56c0'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '수중콘크리트', '물속에 치는 콘크리트. 트레미관·수중불분리성혼화제 사용, 물속 자유낙하 금지.', '["현장타설말뚝·지중연속벽 콘크리트가 대표적 수중(안정액 중) 타설."]'::jsonb, false),
  ('2757a5fe-9bc0-59c4-9932-7fb9dd84cbf0'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '프리플레이스트콘크리트', '굵은골재를 먼저 채우고 그 틈에 모르타르를 주입하는 공법. 수중·보수 공사에 사용.', '[]'::jsonb, false),
  ('136f62e8-2ca1-50df-a600-08e18ec577e8'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '숏크리트', '압축공기로 뿜어 붙이는 모르타르·콘크리트. 급결제 병용 — 터널 라이닝·사면 보호·소일네일링 표면.', '[]'::jsonb, false),
  ('c7a819f3-ca8d-54cf-876e-2fe833804151'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '진공탈수콘크리트', '타설 직후 진공 매트로 잉여수를 빨아내 표면 강도·내마모성을 높이는 공법. 바닥 슬래브·포장용.', '[]'::jsonb, false),
  ('c6cb347f-5ff2-53e4-9f6e-899db2ff0e4a'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '노출콘크리트', '구조체 표면 자체를 마감으로 쓰는 콘크리트. 거푸집 정밀도(콘 자국·줄눈 나누기)·균일 배합·다짐 품질이 곧 마감 품질.', '[]'::jsonb, false),
  ('e7ac96f1-94dd-5545-aa0b-687db95f7362'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 특수환경공법', '폴리머콘크리트', '결합재의 일부/전부를 폴리머로 대체. 고강도·수밀·접착 우수 — 보수재·프리캐스트 특수제품.', '[]'::jsonb, false),
  ('7e9de9b4-9941-55b3-b0f2-ca92651cd175'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', '프리스트레스트콘크리트 (PSC)', 'PS강재로 콘크리트에 미리 압축력을 넣어, 하중중의 인장을 상쇄시키는 콘크리트.', '["원리: ''인장에 약하니 미리 눌러 놓는다'' — 균열 억제·장스팬 실현."]'::jsonb, false),
  ('461aba8c-273a-58a5-9206-2c2b70d0b588'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', '프리텐션 · 포스트텐션', '프리텐션: 강재를 먼저 긴장 → 콘크리트 타설 → 경화 후 절단(부착으로 전달, 공장 제품). 포스트텐션: 콘크리트에 쉬스(관)를 묻고 경화 후 긴장·정착(정착구로 전달, 현장 대형 부재).', '["비교·암기 — ''긴장 시점이 타설 전(프리)이냐 후(포스트)냐'' — 이름 그대로."]'::jsonb, false),
  ('ff93ef2e-7ff6-5a01-b400-d60695e74816'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', 'PS강재 · 쉬스 · 그라우트', 'PS강재: 고강도 강선·강연선. 쉬스: 강재가 지나갈 관. 그라우트: 긴장 후 쉬스 속을 채워 부식 방지·부착시키는 주입재.', '[]'::jsonb, false),
  ('b92d8357-a143-5162-954f-b00973ee5edd'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', '프리캐스트콘크리트 (PC)', '부재를 공장 제작 후 현장 조립. 품질 균일·공기 단축·현장 인력 절감.', '["관건은 접합부: 습식(현장타설 연결)·건식(용접·볼트), 구조 일체성·방수·시공 오차 흡수."]'::jsonb, false),
  ('bb6e9e83-4481-588f-8638-d4b6edf43528'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', '하프PC', '부재의 절반(하부)만 PC로 만들고 상부는 현장 타설해 일체화하는 방식(하프슬래브 등). PC 장점+일체성 절충.', '[]'::jsonb, false),
  ('f66902a4-bafc-51c4-8854-a4f68c43bf1e'::uuid, '2장 · II 거푸집철근타설 · 4절 · 특수콘크리트 · 프리스트레스트프리캐스트', '합성슬래브', '데크플레이트·하프PC 등 선제작 바닥판과 현장 콘크리트가 합성 거동하는 슬래브.', '[]'::jsonb, false),
  ('43b0a782-a318-59c5-b827-5301ecf6425a'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '힘의 평형조건', '정지한 구조물에서 수평력의 합=0, 수직력의 합=0, 모멘트의 합=0이 성립한다는 조건. 반력·부재력 계산의 출발점.', '[]'::jsonb, false),
  ('f64bb7fe-67c1-5e2a-9062-3fae3ccf7f50'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '반력', '지점이 구조물을 받쳐주는 힘. 지점 형식(이동·회전·고정)에 따라 반력 성분 수가 다름(1·2·3개).', '[]'::jsonb, false),
  ('9c126e97-8c4b-5001-8310-8caaff374b17'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '응력', '외력에 대해 부재 내부에 생기는 단위면적당 저항력(응력=힘/단면적(P/A)). 수직응력(인장·압축)과 전단응력.', '[]'::jsonb, false),
  ('1a345e8b-f03e-5e43-91e5-867e9295caa3'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '변형률', '원래 길이에 대한 변형량의 비(변형량/원길이). 무차원.', '[]'::jsonb, false),
  ('9ba75fb7-867a-5d2b-9605-d0cf910fa3e6'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '응력-변형률 곡선', '재료 시험에서 얻는 응력-변형률 관계. 강재: 비례한도-항복점-변형경화-극한-파단의 뚜렷한 단계.', '["콘크리트는 뚜렷한 항복 없이 곡선으로 최대 후 파괴 — 두 재료 곡선 비교가 단골."]'::jsonb, false),
  ('fb72b2a5-802a-5bd5-adcf-7b8fbf454a88'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '탄성 · 소성', '탄성: 하중 제거 시 원상 복귀. 소성: 하중 제거 후에도 영구 변형이 남음.', '["설계 철학과 연결: 사용 상태는 탄성, 극한·내진은 소성 능력(연성)까지 활용."]'::jsonb, false),
  ('e4cd079b-372b-5334-820e-140330a349fe'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '탄성계수 (영계수, E)', '탄성 구간에서 응력/변형률의 비(훅의 법칙). 재료의 ''단단함(변형 저항)'' 지표.', '["강재 E는 콘크리트의 약 8~10배 — 강도와 무관하게 강종이 달라도 E는 거의 일정하다는 점이 포인트."]'::jsonb, false),
  ('64962ec6-8c40-57f9-804a-58e24c5bc538'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '항복점 · 항복강도', '탄성에서 소성으로 넘어가는 경계 응력. 강구조 설계의 기준 강도.', '[]'::jsonb, false),
  ('e0ce617a-b11b-5fab-814c-befbb2542f5b'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 힘응력변형', '인장강도 (재료)', '재료가 견디는 최대 인장응력(극한강도). 항복 후 변형경화를 거쳐 도달.', '[]'::jsonb, false),
  ('7ad05846-825f-5775-b980-4912596a8b14'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 재료의성격', '연성 · 취성', '연성: 파괴 전 큰 소성변형(경고)을 보이는 성질(강재). 취성: 예고 없이 갑자기 파괴(콘크리트·유리).', '["비교·암기 — 내진 설계가 연성을 요구하는 이유: ''무너지기 전에 버티며 알려주는'' 파괴 모드를 만들기 위함."]'::jsonb, false),
  ('23077533-9efc-5161-928e-be9ba03d9a78'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 재료의성격', '인성', '파괴까지 흡수하는 에너지(강도×변형 능력). 충격·지진 저항의 지표.', '[]'::jsonb, false),
  ('f9287071-624f-529f-a408-7b19f83a675f'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 재료의성격', '경도', '표면이 긁힘·눌림에 저항하는 성질. 강도와 상관 — 슈미트해머의 원리이기도.', '[]'::jsonb, false),
  ('c8d57c9c-84f3-59d0-a06d-f6099cd37a3a'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 재료의성격', '피로 · 피로파괴', '반복하중으로 정적 강도보다 낮은 응력에서 파괴되는 현상. 크레인 거더·교량 등 반복 하중 부재의 검토 항목.', '[]'::jsonb, false),
  ('b1e35df9-2db7-5575-aaaf-44362134d507'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 설계법', '허용응력', '재료 기준강도를 안전율로 나눈, 사용 시 허용되는 응력 상한.', '[]'::jsonb, false),
  ('12a11a48-811b-58a8-b91d-862b69e90491'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 설계법', '안전율', '기준강도 ÷ 허용응력. 불확실성(재료·시공·하중)에 대한 여유.', '[]'::jsonb, false),
  ('394643d6-d1fc-5040-85d6-527dda6de270'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 설계법', '허용응력설계법 (ASD)', '사용하중에 의한 응력이 허용응력 이하가 되게 하는 고전적 설계법. 탄성 기반.', '[]'::jsonb, false),
  ('4bba5efa-d0ac-509a-b31a-f8fb9f47fb30'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 설계법', '강도설계법 (USD)', '하중에 하중계수를 곱해 키우고(소요강도), 부재 공칭강도에 강도감소계수를 곱해 줄여(설계강도) 비교하는 설계법. RC 설계의 표준.', '["비교·암기 — ASD(응력을 나눠 여유) ↔ USD(하중은 키우고 강도는 깎아 여유) — 안전율을 두는 위치가 다름."]'::jsonb, false),
  ('c128a108-19a6-5377-80a7-a0faf07d4df6'::uuid, '2장 · III 구조일반 · 1절 · 힘과재료역학기초 · 설계법', '한계상태설계법 (LSD)', '극한한계상태(붕괴)와 사용한계상태(처짐·균열·진동)를 각각 확률을 기반으로 검증하는 현행 설계 철학. 강구조 KDS의 기반.', '[]'::jsonb, false),
  ('c526abc5-a093-50c9-bde8-2377de0bbd71'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '고정하중 (DL)', '구조체·마감·설비 등 항상 작용하는 자중.', '[]'::jsonb, false),
  ('ca2e49ac-30e9-5292-be13-95c0257047f8'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '활하중 (LL)', '사람·가구·적재물 등 위치·크기가 변하는 하중. 용도별 최소값 규정. ※값 확인.', '[]'::jsonb, true),
  ('e1ade8a1-3761-531b-87e1-3881f1f6498e'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '풍하중', '바람에 의한 수평(+지붕 상향) 하중. 높이·형상·지역·지표 거칠기에 좌우 — 고층일수록 지배적.', '[]'::jsonb, false),
  ('a55364d8-7e11-5f16-b3f5-534b9534f690'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '지진하중', '지반 진동으로 건물 질량에 생기는 관성력(수평 지배).', '["무거울수록·높을수록 큼 — ''지진력은 질량에 비례''가 핵심 논리(F=ma).", "비교·암기 — 풍하중(면적·형상이 지배) ↔ 지진하중(질량이 지배) — 무엇에 비례하는지로 구분."]'::jsonb, false),
  ('4365ba04-93f0-5985-a83b-72ef5aea971a'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '적설하중', '지붕에 쌓인 눈의 하중. 지역별 기본값과 지붕 형상 계수. ※확인.', '[]'::jsonb, true),
  ('39285fcb-4621-59ed-bbee-a3bbbb030798'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '토압 · 수압', '지하 외벽·옹벽이 받는 흙·물의 횡압. 지하수위가 높으면 부력 검토도 병행.', '[]'::jsonb, false),
  ('7b15f81a-ec1a-5aee-9e37-644d8cc7606a'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '충격하중', '낙하·주행 등 동적 효과를 정적 하중에 할증하는 하중(크레인·주차장 등).', '[]'::jsonb, false),
  ('c9b04ecc-8048-55c7-9470-c27c5139b0e5'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 하중의종류', '하중조합', '동시에 작용할 수 있는 하중을 계수 곱해 더한 설계용 조합(예: 1.2D+1.6L 등). 가장 불리한 조합으로 설계. ※계수 확인.', '[]'::jsonb, true),
  ('5262ff79-aa9f-5485-9f05-4cf55c13dbcf'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 부재력단면력', '축력 (N)', '부재 길이 방향의 압축·인장력. 기둥·가새·트러스의 지배 부재력.', '[]'::jsonb, false),
  ('52a8ff9e-3ff6-5333-8b96-6cf3751a7a8d'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 부재력단면력', '전단력 (V)', '단면을 어긋나게 자르려는 힘. 보 단부(지점 부근)에서 최대.', '[]'::jsonb, false),
  ('ffb9cf7c-bea8-54c7-b843-0c5466793e2d'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 부재력단면력', '휨모멘트 (M)', '부재를 구부리는 힘. 단순보 중앙에서 최대(등분포 시 wL²/8).', '[]'::jsonb, false),
  ('a4757518-750e-5b54-a41a-2822a8db1dc7'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 부재력단면력', '비틀림모멘트 (T)', '부재를 축 둘레로 비트는 모멘트. 곡선보·편심 하중 부재에서 검토.', '[]'::jsonb, false),
  ('5366fb9f-dbcc-5b91-821f-1833cc4bbf64'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 부재력단면력', '전단력도(SFD) · 휨모멘트도(BMD)', '부재 길이에 따른 V·M의 분포 그림.', '["관계: 하중 → (적분) → 전단력 → (적분) → 휨모멘트도. V=0인 곳에서 M 최대 — 그림 그리기가 면접 단골."]'::jsonb, false),
  ('6fea8abb-3298-5abf-ac49-3222e606fc96'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 단면의성질', '단면2차모멘트 (I)', '단면이 휨(처짐)에 저항하는 기하학적 성능. 춤(높이)의 세제곱에 비례.', '["''보는 넓적하게보다 세워서 써야 하는 이유''의 근거."]'::jsonb, false),
  ('ac81ec59-83eb-5cfd-90bc-7f075ecf237a'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 단면의성질', '단면계수 (Z)', 'I ÷ 연단거리. 휨응력 산정(M/Z)에 쓰는 강도 측면의 단면 성능.', '[]'::jsonb, false),
  ('fc926e9e-a242-5887-bfa8-4e748b41bba3'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 단면의성질', '중립축', '휨을 받는 단면에서 인장도 압축도 없는 축. 위는 압축·아래는 인장(정모멘트 기준).', '[]'::jsonb, false),
  ('44666724-241f-5569-b535-f8b159545765'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 변형안정문제', '처짐', '휨 부재의 연직 변형. 강도가 아니라 사용성(균열·진동·미관)의 문제.', '["처짐은 EI(강성)에 반비례, 지간의 세제곱~네제곱에 비례 — 장스팬일수록 처짐이 지배."]'::jsonb, false),
  ('998a498c-719c-527d-8184-1c9c61303307'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 변형안정문제', '처짐 한계 (사용성)', '지간의 일정 비율(L/240 등 부위별)로 제한. ※기준값 확인.', '[]'::jsonb, true),
  ('f7882701-5986-532c-b503-bb5437ab44c9'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 변형안정문제', '좌굴', '세장한 압축재가 강도 도달 전 옆으로 휘며 급격히 불안정해지는 파괴.', '["오일러 하중: 길이 제곱에 반비례, EI에 비례 — ''가늘고 길수록 위험''."]'::jsonb, false),
  ('047bdf92-4375-5e7f-8fda-58b360b4b1ac'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 변형안정문제', '세장비', '유효좌굴길이 ÷ 단면 회전반경. 좌굴 취약성의 지표(클수록 위험), 압축재 설계의 핵심 변수.', '[]'::jsonb, false),
  ('ce9e5488-16e8-5961-974e-f5757cbeb9f0'::uuid, '2장 · III 구조일반 · 2절 · 하중과부재력 · 변형안정문제', '유효좌굴길이', '지점 조건에 따라 실제 길이에 계수를 곱한 좌굴 계산용 길이(양단 힌지=1.0, 양단 고정=0.5, 캔틸레버=2.0).', '["비교·암기 — ''어떻게 잡혀 있느냐가 길이를 바꾼다'' — 지점 조건별 계수 그림으로 암기."]'::jsonb, false),
  ('547ccd2a-887f-5766-a8ec-a28e36f7e398'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '정정구조 · 부정정구조', '정정: 평형조건만으로 풀림(여분 구속 없음). 부정정: 변형 조건까지 필요(여분 구속 있음).', '["부정정의 실무 의미: 한 부재가 손상돼도 하중 재분배 가능(여용성) — 실제 건물 대부분은 부정정."]'::jsonb, false),
  ('6eb7fd4c-6aaf-574d-b59d-b3c1c5b84fd0'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '라멘구조', '기둥과 보를 강접합한 골조. 접합부가 모멘트를 전달 — 평면 자유·개구부 큼.', '["횡력을 부재의 휨으로 저항 → 변형(횡변위)이 큰 편."]'::jsonb, false),
  ('ba39e74d-4ff6-5de1-af6c-7eb11103a99b'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '벽식구조', '내력벽이 기둥·보를 대신해 수직·수평력을 받는 구조. 층고 절감 — 국내 아파트 표준, 평면 변경 곤란.', '[]'::jsonb, false),
  ('043e560b-0b5e-5f19-a1c9-5e6577457086'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '무량판구조 (플랫슬래브)', '보 없이 슬래브가 기둥에 직접 지지되는 구조. 층고 절감·설비 자유.', '["최대 약점: 기둥 주변 펀칭전단 — 전단 보강(스터럽·전단스터드)과 시공 품질이 안전과 직결."]'::jsonb, false),
  ('270821df-6895-5f2e-b3ee-3e5092c9cc7c'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '펀칭전단', '기둥이 슬래브를 뚫고 올라가듯 발생하는 국부 전단파괴. 무량판 붕괴 사고의 전형적 메커니즘.', '[]'::jsonb, false),
  ('c0f9cfa2-abeb-550f-9f52-4fd7a55872af'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 해석관점의분류', '지판 · 주두', '펀칭전단 보강을 위해 기둥 위 슬래브를 두껍게(지판, 드롭패널) 하거나 기둥머리를 넓힘(주두, 캐피탈).', '["비교·암기 — 플랫플레이트(지판 없음) vs 플랫슬래브(지판·주두 있음)로 구분하기도 함."]'::jsonb, false),
  ('6867880e-bdd8-5e3b-aa3a-dd620c2b6c01'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '트러스', '부재를 삼각형으로 짜 축력(인장·압축)만으로 저항하는 구조. 장스팬 지붕·가설교량.', '["절점은 힌지로 가정 — ''삼각형은 변하지 않는다''가 원리."]'::jsonb, false),
  ('4b4d1aa4-5753-585e-a4d9-b8b419f77883'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '아치', '곡선 형상으로 하중을 압축력 위주로 지반에 전달하는 구조. 인장에 약한 재료(석재)로 장스팬을 만든 고전 해법.', '[]'::jsonb, false),
  ('fcf0bdd0-1ffa-54a5-9cdd-4d1eacd94d1c'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '케이블구조', '인장만 받는 케이블로 지붕·교량을 매다는 구조. 자중 대비 최고 효율 — 형상 안정(진동) 관리가 과제.', '[]'::jsonb, false),
  ('04bbd9eb-fe99-55d4-a914-b7a7589dc4d7'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '셀구조', '곡면 판이 면내력(막응력) 위주로 저항하는 구조. 얇은 두께로 대공간(돔) 실현.', '[]'::jsonb, false),
  ('a8734fa5-d250-5e16-8167-508f7ffb5f4d'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '막구조', '코팅 직물막에 인장(장력)을 주어 지붕을 만드는 구조. 경량·대공간(경기장).', '[]'::jsonb, false),
  ('e511d77c-7cf0-5080-bfae-c20fda529eb9'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 특수형식', '스페이스프레임', '입체 트러스. 볼 조인트+파이프로 대공간 지붕을 격자로 짬.', '[]'::jsonb, false),
  ('d48b6d5a-5b8c-5e34-9570-5d2a58ad6bb3'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '횡력저항시스템', '바람·지진의 수평력을 받는 시스템의 총칭. 모멘트골조·전단벽·가새골조와 이들의 조합.', '[]'::jsonb, false),
  ('5a5ba66e-11f6-5c77-ace2-7ac7cd6ce963'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '전단벽', '벽체 면내 강성으로 횡력을 받는 벽. 강성 크고 변위 작음 — 코어·계단실 벽 활용.', '[]'::jsonb, false),
  ('0d86417e-a81a-51f2-bdb1-0f003519aab6'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '코어 (구조)', '엘리베이터·계단·설비 샤프트를 묶은 중앙부. 전단벽 코어가 고층 건물 횡력의 중추.', '[]'::jsonb, false),
  ('c66a8549-f3eb-5c1f-ac74-9b0c21895eec'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '가새골조', '대각 가새로 횡력을 축력으로 전달하는 골조. 강성·효율 우수, 개구부 제약.', '["중심가새(축선 일치)와 편심가새(링크로 에너지 흡수) 구분."]'::jsonb, false),
  ('1aef369a-a5ca-5643-8566-fd2b4e722459'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '메가브레이스', '여러 층을 가로지르는 초대형 가새. 외곽 기둥과 함께 건물 전체를 하나의 거대 트러스처럼 작동시킴 — 초고층 효율 시스템.', '[]'::jsonb, false),
  ('ed626fa5-a031-5ce3-8641-1a07825ed302'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '아웃리거', '코어와 외곽 기둥을 강성 큰 벽·트러스로 연결해, 외곽 기둥의 축력으로 코어의 전도 모멘트를 분담시키는 시스템.', '["초고층 횡변위 저감의 대표 해법. 설치 층(기계층) 선정이 설계 포인트."]'::jsonb, false),
  ('413a1588-1947-5373-bb35-b231aad30bbd'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '벨트트러스', '아웃리거 층에서 외곽 기둥들을 띠처럼 묶는 트러스. 아웃리거 효과를 외곽 전체 기둥으로 확산.', '[]'::jsonb, false),
  ('39782458-b41a-5f2b-87de-b199ee170910'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '튜브구조', '외곽 기둥·보를 촘촘히 배치해 건물 외피 전체가 캔틸레버 튜브처럼 저항하는 시스템. 전단지연 현상이 검토 이슈.', '[]'::jsonb, false),
  ('5769b5e6-1285-5a18-8708-8415e70cb4b3'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '다이아그리드', '외곽을 대각 격자 부재로 짠 시스템. 기둥 없이 대각재가 중력+횡력을 동시에 부담 — 비정형 초고층에 유리.', '[]'::jsonb, false),
  ('bc553f91-0e6f-5482-886f-867515ff4d71'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 횡력저항시스템', '필로티 (연약층)', '하층부 벽 없이 기둥만으로 개방한 층. 상하층 강성 급변(연약층)으로 지진 시 손상 집중 — 내진 취약 유형의 대명사.', '["대책: 1층 기둥 보강·전단벽 추가·연성 확보."]'::jsonb, false),
  ('14d36903-453b-5a5b-ba0a-79b5d97a8339'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 부재특수부위', '전이보 (트랜스퍼거더)', '상부 기둥·벽 하중을 받아 하부의 다른 기둥 배치로 옮겨주는 대형 보(주상복합 저층부 등).', '["하중 집중으로 춤이 매우 큼 — 매스콘크리트·과밀 배근 관리 이슈 동반."]'::jsonb, false),
  ('28ad8379-20c4-5b98-94c5-2b51229145bc'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 부재특수부위', '캔틸레버', '한쪽만 고정되고 반대쪽이 자유단인 내민 부재(발코니·차양). 고정단 상부가 인장 — 배근 방향 단골 문제.', '[]'::jsonb, false),
  ('f2dbe4b4-10af-5ea4-81e6-eb6c277285cd'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 부재특수부위', '헌치', '보·슬래브 단부를 비스듬히 키운 부분. 단부 모멘트·전단 보강.', '[]'::jsonb, false),
  ('7947ef2a-6722-5c8d-985e-fd3fa0848a1a'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 부재특수부위', '옹벽', '토압을 받아 흙을 지지하는 벽(캔틸레버식·중력식·부벽식).', '["안정 검토 3가지: 전도·활동·지지력(침하) — 3대 검토 항목이 시험 단골."]'::jsonb, false),
  ('7184f310-2821-5c19-8f39-f5899d71a34e'::uuid, '2장 · III 구조일반 · 3절 · 구조형식시스템 · 부재특수부위', '이중골조시스템', '모멘트골조+전단벽(가새)을 병용, 역할을 분담시키는 시스템. 강성(벽)과 연성(골조)을 함께 확보.', '[]'::jsonb, false),
  ('faec92df-a23e-5948-b7f3-be363ccbafea'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '내진설계', '지진에 대해 인명 보호를 기본 목표로 구조물의 강도·연성을 확보하는 설계.', '["철학: ''작은 지진은 무손상, 중간 지진은 보수 가능, 큰 지진은 붕괴 방지(인명 보호)''."]'::jsonb, false),
  ('3524f2fd-8096-5f74-a544-3f1cad2e4558'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '내진 · 제진 · 면진', '내진: 강도·연성으로 견딤. 제진: 장치(댐퍼)로 에너지 흡수. 면진: 기초 위 절연층으로 지진력 자체를 차단.', '["비교·암기 — ''견딘다-줄인다-끊는다'' 3단계. 비용·성능도 대체로 이 순서로 상승."]'::jsonb, false),
  ('f8988981-ded2-59db-9111-3f3c38a01b32'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '댐퍼', '진동 에너지를 열로 소산시키는 제진 장치(점성·이력·마찰형 등). 기존 건물 내진 보강에도 사용.', '[]'::jsonb, false),
  ('41bacdc3-eaa6-515f-af08-3485371ecb8f'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '면진받침 (적층고무)', '고무+강판 적층 받침으로 수평으로 부드럽게, 수직으로 단단하게 — 건물 고유주기를 길게 만들어 지진력을 줄임.', '[]'::jsonb, false),
  ('c649ee32-2fb6-512d-916c-05cf9cd67abc'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '연성설계', '부재가 항복 후에도 변형하며 에너지를 흡수하도록 상세(배근·구속)를 확보하는 설계. 내진의 핵심 개념.', '[]'::jsonb, false),
  ('50da069d-57ec-5d94-b961-a127d5b7be28'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '강기둥-약보', '보가 기둥보다 먼저 항복하도록 강도 위계를 두는 원칙.', '["이유: 보 항복(국부 손상·에너지 흡수)은 허용, 기둥 항복(층 붕괴)은 금지 — ''기둥은 마지막까지 서 있어야 한다''."]'::jsonb, false),
  ('ef74c8b5-db40-55f2-8dc2-162d005ca9a5'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '소성힌지', '부재가 항복해 회전하며 에너지를 흡수하는 관절 구간. 보 단부에 유도하는 것이 연성설계의 목표.', '[]'::jsonb, false),
  ('37244973-f7ce-52b7-8dd9-627bb0c98e93'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '층간변위', '인접 층 사이의 상대 수평변위. 구조 손상·마감 파손·커튼월 추종 성능의 지표 — 허용치 규정. ※확인.', '[]'::jsonb, true),
  ('a069006e-2713-5341-be8f-139ae2774e80'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '고유주기', '구조물이 자유진동할 때 1회 왕복에 걸리는 시간. 높고 유연할수록 김.', '["지반 주기와 건물 주기가 가까우면 공진 — 응답 증폭."]'::jsonb, false),
  ('1ae49b78-7de7-5789-9000-5611ef94b66d'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '공진', '외력 주기와 고유주기가 일치해 진동이 증폭되는 현상. 멕시코시티 지진 피해의 고전적 사례 논리.', '[]'::jsonb, false),
  ('4b58a401-e5b2-55fd-a10b-d6a1c1e335be'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 내진설계개념', '풍동실험', '축소 모형을 풍동에 넣어 풍압·풍진동(와류진동)을 계측하는 실험. 초고층·비정형 필수 검증.', '[]'::jsonb, false),
  ('9c1dc153-4d23-5c07-adcc-08251be48a54'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 부재일반', '기둥 · 보 · 슬래브 · 벽체 (부재 구분)', '기둥(수직·축력+휨) / 보(수평·휨+전단) / 슬래브(면·휨) / 벽체(면·수직+횡력) — 힘의 종류로 부재를 정의하면 답이 깔끔.', '[]'::jsonb, false),
  ('4fadb852-3aaa-5e88-847d-515cab28334b'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 부재일반', '큰보 (거더) · 작은보 (빔)', '큰보: 기둥과 기둥을 직접 잇는 보. 작은보: 큰보 사이에 걸리는 보(슬래브 하중을 큰보로 전달).', '["비교·암기 — 하중 흐름: 슬래브 → 작은보 → 큰보 → 기둥 → 기초 → 지반. 이 한 줄이 구조 전체의 지도."]'::jsonb, false),
  ('c31c830a-0ff9-584b-9e1a-1fb5ab7b71d7'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 부재일반', '1방향 · 2방향 슬래브', '변장비(장변/단변)에 따라 하중이 한 방향(1방향, 비 2 초과)으로 가는지 두 방향(2방향, 2 이하)으로 가는지 구분. ※기준 확인.', '["1방향은 단변 방향이 주근 — 배근 방향 문제와 연결."]'::jsonb, true),
  ('e05f5e30-3c23-5099-b67e-fd0fa6d79238'::uuid, '2장 · III 구조일반 · 4절 · 내진부재일반 · 부재일반', '내력벽 · 비내력벽', '내력벽: 구조 하중을 받는 벽(철거 불가). 비내력벽: 공간 구획용(경량벽 등).', '["리모델링 시 내력벽 철거 사고 — 실무·안전 이슈로 자주 등장."]'::jsonb, false),
  ('ae01dcbc-5a73-565a-84cc-b563e3821073'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', '탄소강', '철+탄소(2% 이하)의 강. 탄소량이 늘면 강도·경도↑, 연성·용접성↓ — 구조용은 저탄소강.', '[]'::jsonb, false),
  ('05142d89-616e-5fd2-ba5c-47939647cada'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', '합금강', '니켈·크롬·망간 등을 첨가해 강도·인성·내식성을 개선한 강.', '[]'::jsonb, false),
  ('657a74a4-27ef-5976-910a-801c5182dd64'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', '스테인리스강', '크롬 12% 이상으로 내식성을 부여한 강. 외장재·긴결철물 등.', '[]'::jsonb, false),
  ('09111bab-da51-5c2a-98a9-4f79cd76f505'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', '내후성강', '구리·크롬 첨가로 표면에 치밀한 녹(안정 녹층)을 만들어 도장 없이 견디는 강. 교량·노출 강구조.', '[]'::jsonb, false),
  ('c09b9f47-fbc0-5fe7-b101-0d211da2e6eb'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', 'TMC강', '열가공제어(TMCP)로 만든 강 — 탄소량을 낮추고도 고강도, 용접성 우수, 두께가 커져도 항복강도 저하 없음.', '["초고층·후판 부재의 표준적 선택."]'::jsonb, false),
  ('9b8e4777-bb94-5bd4-b39c-c0e2bca4f4b0'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의분류', 'SS · SM · SN 강재 구분', 'SS(일반구조용): 용접성 보장 없음 — 볼트 접합 소부재용. SM(용접구조용): 용접성 확보. SN(건축구조용): 내진 성능(항복비상한·항복강도 범위·판두께 방향 성능)까지 규정.', '["비교·암기 — ''볼트용 SS → 용접용 SM → 내진용 SN'' — 요구 성능이 한 단계씩 추가되는 계보."]'::jsonb, false),
  ('818e162d-0946-5696-8691-540bef7f7fcb'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 형태별강재', '형강 (H·I·ㄱ·ㄷ·T)', '압연으로 만든 단면 강재. H형강이 기둥·보의 주력(플랜지+웨브).', '["H형강 표기: H-춤×폭×웨브두께×플랜지두께."]'::jsonb, false),
  ('29b0170d-14de-5d14-8459-f3b7b6c3326a'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 형태별강재', '강관', '원형·각형 중공 단면. 좌굴에 유리(모든 방향 회전반경 동일) — 기둥·트러스에 적합. CFT의 외피.', '[]'::jsonb, false),
  ('c7206c8d-7ef6-5a8d-a0fd-131d8e497a6a'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 형태별강재', '경량형강', '얇은 강판을 냉간 성형한 형강(C형강 등). 2차 부재(중도리·스터드용) — 국부좌굴 주의.', '[]'::jsonb, false),
  ('1fd3cf3f-62ee-5ab1-8f7d-23cb6ea090c7'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 형태별강재', '강판 · 후판', '판재 강. 두께 6mm 이상을 후판으로 통칭 ※기준 확인 — 두꺼울수록 용접·인성 관리 중요.', '[]'::jsonb, true),
  ('24da7c38-0333-5666-aac6-19719b0f92d8'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '열처리 (불림·풀림·담금질·뜨임)', '불림(공랭, 조직 균질화) / 풀림(노냉, 연화·응력 제거) / 담금질(급랭, 경화) / 뜨임(재가열, 인성 회복).', '["비교·암기 — ''담금질로 굳히고 뜨임으로 달랜다'' — 담금질+뜨임은 세트."]'::jsonb, false),
  ('2a0c756b-77b4-5d3b-9450-b227921c67e3'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '탄소당량 (Ceq)', '탄소+합금원소를 탄소 기준으로 환산한 값. 클수록 용접 균열 위험 — 용접성의 지표.', '[]'::jsonb, false),
  ('d79ee00c-05b4-51fa-b186-22d78e295133'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '취성파괴 (강재)', '연성 변형 없이 갑자기 쪼개지는 파괴. 저온·노치(결함)·두꺼운 판·급속 하중에서 위험.', '[]'::jsonb, false),
  ('46cd942c-4278-566b-b3f3-7fbfd80d3194'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '라멜라테어링', '판두께 방향 인장을 받을 때 강판 내부 층상 개재물을 따라 찢어지는 결함.', '["두꺼운 판의 십자·T 용접부에서 발생 — 대책: 판두께 방향 성능 보증 강재(SN C종), 이음 상세 개선."]'::jsonb, false),
  ('69ebd84d-50fc-5beb-8a4c-017e29fe4230'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '저온취성', '온도가 낮아지면 인성이 급감해 취성파괴되기 쉬워지는 성질. 샤르피 충격시험으로 평가.', '[]'::jsonb, false),
  ('e63b7a72-d52d-569c-a7ae-eb9f39ef5724'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '강재의 부식과 방청', '부식: 산소+물에 의한 전기화학적 녹. 방청: 도장, 아연도금(희생방식), 전기방식, 내후성강.', '["비교·암기 — 아연도금의 원리 = ''아연이 대신 녹슬어 준다''(희생양극) — 원리 설명이 가점 포인트."]'::jsonb, false),
  ('bbd588ce-0de0-5f19-b012-7470988e8400'::uuid, '2장 · IV 강재철골 · 1절 · 강재재료 · 강의처리성질', '밀시트 (제품성적서)', '강재 제조사의 성적 증명서(화학성분·기계적 성질·규격). 강재 반입 검사의 기본 서류.', '[]'::jsonb, false),
  ('a113d9af-bbdc-59ef-a469-e9961b1f31cf'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 공장제작', '공장제작 (원척도·마킹·절단)', '공장에서 부재를 제작하는 공정: (원척도·형판) → 마킹(금긋기) → 절단 → 구멍뚫기 → 조립·용접 → 검사 → 도장 → 출하.', '["철골 품질의 대부분은 공장에서 결정 — 공장 검수(제작 검사)가 중요."]'::jsonb, false),
  ('aa382517-21ea-562d-9116-eaef441adca5'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 공장제작', '가조립', '출하 전 공장에서 부재를 임시 조립해 치수·접합 정합성을 확인하는 절차(대형·복잡 구조물).', '[]'::jsonb, false),
  ('d985feaf-77a1-573b-921f-fe706372051e'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 주각부', '앵커볼트', '기초 콘크리트에 묻어 철골 기둥 베이스를 고정하는 볼트. 위치 정밀도가 세우기 품질을 좌우.', '[]'::jsonb, false),
  ('781863e7-92da-5022-84b4-0e0496cea7b7'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 주각부', '고정매입 · 가동매입 · 나중매입', '고정매입: 타설 전 정확히 고정(대규모 표준·수정 불가). 가동매입: 상부를 조정 가능하게 매입. 나중매입: 박스를 두고 나중에 설치·그라우팅(소규모).', '["비교·암기 — ''정확·튼튼(고정) ↔ 융통성(가동·나중)''의 트레이드오프로 정리."]'::jsonb, false),
  ('da34216f-7a29-5c1b-b338-91047cfd7135'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 주각부', '베이스플레이트', '기둥 하단의 넓은 판. 기둥 축력을 기초에 분산 전달.', '[]'::jsonb, false),
  ('de03edff-0e5a-527f-99e7-0e49d392b660'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 주각부', '기초상부 고름질 (그라우팅·패드)', '베이스플레이트 밑을 수평·밀실하게 만드는 작업 — 전면바름법, 나중채워넣기(+중심 패드·너트 조정) 후 무수축 그라우팅.', '["무수축 모르타르 사용이 핵심(수축하면 들뜸)."]'::jsonb, false),
  ('e08c34e4-2838-5eca-9294-b04357eb06fa'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 세우기', '세우기 · 건립공법', '기둥→보 순으로 블록 단위 조립, 크레인 계획(대수·위치·양중 하중)과 부재 반입 순서가 공정의 뼈대.', '[]'::jsonb, false),
  ('5e060e49-2a07-5bab-8538-320a30cb27e4'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 세우기', '수직도 계측', '세우기 후 트랜싯·추 등으로 기둥 수직도를 측정·수정(와이어 당김)하는 작업, 허용오차 관리. ※오차 기준 확인.', '[]'::jsonb, true),
  ('10507c62-9127-5802-86b7-4e80573efcbe'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 세우기', '가볼트 조임', '본조임 전 부재 위치를 잡는 임시 볼트. 전체의 일정 비율 이상+최소 개수 확보. ※비율 확인.', '["가볼트는 본조임에 재사용 금지(변형 우려)."]'::jsonb, true),
  ('fe1d9941-b2bc-597b-8ced-090f16fdb42d'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '리벳접합', '가열 리벳을 박아 접합하는 과거 공법. 소음·품질 문제로 현재 거의 사용 안 함(역사적 맥락으로 이해).', '[]'::jsonb, false),
  ('d009c976-55aa-5792-8686-4a65d32f3c8c'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '일반볼트접합', '일반 볼트의 전단·지압으로 힘을 전달. 진동에 풀림 — 가설·소규모 한정.', '[]'::jsonb, false),
  ('03358b98-3e62-5dc8-bd88-7b5723d90785'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '고장력볼트 (HTB)', '고강도 볼트를 강하게 조여(도입장력) 부재 간 마찰로 힘을 전달하는 현대 표준 접합.', '["장점: 소음 없음, 품질 균일, 피로에 강함, 해체 가능."]'::jsonb, false),
  ('b625e00c-e9cf-50af-ae68-b8763ff2ba02'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', 'TS볼트 (토크쉬어)', '규정 토크에서 핀테일이 부러지며 조임 완료가 눈으로 확인되는 고장력볼트. 현장 시공성·검사성 우수 — 현재 주류.', '[]'::jsonb, false),
  ('a6f73ee0-7f17-5903-802f-9d0b11697a7d'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '마찰접합', '도입장력에 의한 부재면 마찰로 힘 전달(고장력볼트의 표준 거동). 마찰면 처리(흑피 제거·자연 녹) 필수 — 도장 금지.', '["미끄럼계수 확보가 성능의 전제. ※계수값 확인."]'::jsonb, true),
  ('db1f31cd-88a4-59c9-b6da-10cd0dd8f916'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '인장접합', '볼트 축방향 인장으로 힘을 전달하는 접합(엔드플레이트 접합 등).', '[]'::jsonb, false),
  ('8171939f-a885-50e3-9862-88920024da04'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 볼트접합', '지압접합', '볼트 몸통이 구멍에 눌려(지압) 힘을 전달. 미끄럼짐이 허용되는 경우 한정.', '["비교·암기 — 힘 전달 3방식: 마찰(면끼리) / 인장(볼트 축) / 지압(볼트 몸통) — HTB의 표준은 마찰."]'::jsonb, false),
  ('ed45d611-dddc-5be7-8b82-48368fbbda5f'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 조임관리', '토크관리법', '규정 토크값으로 조임을 관리하는 방법(토크렌치). 토크-장력 관계의 산포가 약점.', '[]'::jsonb, false),
  ('7761481e-ed9a-540f-99cd-43b7b8f588ae'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 조임관리', '너트회전법', '밀착(스너그) 상태에서 너트를 규정 각도(예: 120°) 더 돌려 장력을 도입하는 방법. ※각도 확인.', '[]'::jsonb, true),
  ('78126ea6-d4ed-5222-b4a3-0b1f90778900'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 조임관리', '조임 검사 (금매김)', '1차 조임 후 볼트·너트·와셔·모재에 일직선 금긋기 → 본조임 후 회전량으로 공회전·미조임 판별.', '["TS볼트는 핀테일 파단+금매김 회전 확인. 조임 순서: 중앙에서 단부로."]'::jsonb, false),
  ('7d63dae8-63b6-547f-a676-4c876eaea9fa'::uuid, '2장 · IV 강재철골 · 2절 · 철골세우기볼트접합 · 조임관리', '도입장력 · 미끄럼계수', '도입장력: 볼트에 넣는 초기 인장력(설계볼트장력 이상). 미끄럼계수: 마찰면의 마찰 성능(0.5 표준 통용 ※확인).', '[]'::jsonb, true),
  ('a0c147d2-36b9-50ce-8a9f-ed1cdfe6517a'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접방법', '피복아크용접 (SMAW)', '피복 용접봉과 모재 사이 아크로 녹여 접합하는 수동 용접. 전자세 가능·장비 간단 — 현장 용접의 기본.', '[]'::jsonb, false),
  ('cb48c3df-ecc9-5e8c-82f0-6fc8224ba831'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접방법', 'CO2 아크용접', 'CO2 가스로 용융부를 보호하며 와이어를 연속 공급하는 반자동 용접. 능률 높음 — 공장·현장 주력.', '["바람에 취약(가스 날림) — 현장 방풍 조치 필수."]'::jsonb, false),
  ('8febc1c2-0255-5d82-acb3-2099cefe9844'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접방법', '서브머지드아크용접 (SAW)', '플럭스 가루 속에 아크를 묻고 대전류로 용접하는 자동 용접. 하향 전용·고능률 — 공장 후판 긴 용접부.', '[]'::jsonb, false),
  ('2baa56b2-ce41-5595-abe1-554ceb27024d'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접방법', '일렉트로슬래그용접', '수직 이음 전용 자동 용접. 두꺼운 판을 1패스로 — 박스기둥 다이어프램 용접 등.', '[]'::jsonb, false),
  ('3002dad1-e2f3-5fd1-a294-c2f38321d2a1'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접방법', '스터드용접', '스터드볼트를 순간 아크로 모재에 붙이는 전용 용접. 합성보 전단연결재 시공법.', '[]'::jsonb, false),
  ('9d3d96bf-433c-5be1-ae15-caf601d4301a'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '맞댐용접 (그루브용접)', '부재를 맞대고 개선(홈)을 파서 전단면을 녹여 잇는 용접. 모재와 동등 강도 — 완전용입이 원칙.', '["응력 흐름이 매끄러워 주요 구조 이음(기둥 이음, 보 플랜지)에 사용."]'::jsonb, false),
  ('38d7861f-6af6-5bd7-bb3a-32dc6cf3ae6d'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '모살용접 (필릿용접)', '직교하는 두 면의 구석에 삼각형 용착금속을 붙이는 용접. 개선 불필요·경제적 — 겹침·T이음의 표준.', '["비교·암기 — 맞댐(전단면 용입·강함·비쌈) ↔ 모살(구석 붙임·간편·전단 전달) — 단면 그림과 함께 답하면 확실."]'::jsonb, false),
  ('8921c89e-d8d9-581e-9a19-2aefc6536405'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '개선 · 루트', '개선: 용입을 위해 판 끝을 가공한 홈(V·X·K형). 루트: 개선 밑바닥의 간격·면.', '["개선각·루트간격이 부적정하면 용입불량 — 용접 전 검사 항목."]'::jsonb, false),
  ('52346346-ab4c-5b42-9e81-4dcfa16eb671'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '엔드탭', '용접 시·종단부의 결함(크레이터 등)을 부재 밖으로 빼내기 위해 양 끝에 붙이는 보조판. 용접 후 절단.', '[]'::jsonb, false),
  ('18893693-94dd-5d05-9ed8-572d9537c418'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '뒷댐재', '한쪽에서만 용접할 때 뒷면에 대는 받침재(백킹). 뒷면 용락 방지·완전용입 확보.', '[]'::jsonb, false),
  ('61641777-b563-581a-b0fd-354ef4b3a561'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '스캘럽', '용접선이 교차하지 않도록 모재에 파 놓는 부채꼴 홈.', '["용접 교차부의 열영향 중첩·결함 방지. 최근엔 논스캘럽 공법도 사용(응력집중 저감)."]'::jsonb, false),
  ('f88e2b1b-1457-570a-9473-6602c548e01c'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '위빙', '용접봉을 좌우로 흔들며 나아가는 운봉. 비드 폭 확보.', '[]'::jsonb, false),
  ('b03e924f-25c2-5c7f-99ca-13712105c86a'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '용접자세 (F·H·V·O)', '아래보기(F)·수평(H)·수직(V)·위보기(O). 아래보기가 품질·능률을 최상 — 공장제작이 유리한 이유.', '[]'::jsonb, false),
  ('5a0e3b4d-767f-56b5-a79d-231c01e8cfa9'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 이음형식과용어', '예열', '용접 전 모재를 데우는 것. 급랭에 의한 경화·저온균열 방지.', '["필요조건: 두꺼운 판, 저온 환경, 탄소당량 높은 강재. ※온도 기준 확인."]'::jsonb, true),
  ('d96fff38-4690-5b7e-93df-f75551d7a70c'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '블로홀', '용착금속 속 기공(가스 구멍). 원인: 습기(용접봉·개선면)·녹·바람. 대책: 용접봉 건조·청소·방풍.', '[]'::jsonb, false),
  ('6fa2b96e-c01e-5a05-b318-e449a2600d6f'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '슬래그혼입', '슬래그(용접 찌꺼기)가 용착금속 속에 남는 결함. 층간 슬래그 제거 불량이 원인.', '[]'::jsonb, false),
  ('b04ee6b0-4447-576c-9181-439c4211cab3'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '언더컷', '모재가 파여 홈으로 남는 결함. 전류 과대·운봉 불량, 응력집중 → 피로 균열의 기점.', '[]'::jsonb, false),
  ('16703988-5740-5e70-ad60-ae4a2b53f13b'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '오버랩', '용착금속이 모재에 융합되지 않고 겹쳐 얹힌 결함. 전류 과소.', '["비교·암기 — 언더컷(전류 과대·파임) ↔ 오버랩(전류 과소·얹힘) — 전류로 대비되는 짝."]'::jsonb, false),
  ('5354d9c7-72b8-5f2b-b2fc-417130e2dccc'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '크레이터', '용접 종단의 오목 파임. 종단 처리(되돌림)·엔드탭으로 방지.', '[]'::jsonb, false),
  ('9c90b95a-c2bb-5ac0-a18c-4b6cf8bae5b2'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '피트', '표면에 열린 작은 기공 구멍.', '[]'::jsonb, false),
  ('629450a9-cc4d-5c19-a100-31e4255f7d25'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '용입불량', '루트까지 녹지 못해 이음 뿌리가 붙지 않은 결함. 개선각 부족·전류 부족·루트간격 과소.', '[]'::jsonb, false),
  ('8584c574-f962-51c1-bc85-50aa96fd8889'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '용접균열', '가장 위험한 결함. 고온균열(응고 중)·저온균열(수소·경화·구속 — 지연 발생). 예열·저수소계 용접봉으로 대책.', '[]'::jsonb, false),
  ('6a9a4f11-6b95-504b-8bd7-efc542f4862f'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접결함형태별', '각장 · 목두께', '모살용접 치수: 각장(다리 길이), 목두께(유효 두께 = 각장×0.7). 강도 계산은 목두께 기준.', '["각장 부족 = 강도 부족 — 외관검사 측정 항목."]'::jsonb, false),
  ('9e24f60d-1b12-5cd3-af8b-c79d648c2468'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '외관검사 (VT)', '육안+게이지로 비드 형상·각장·언더컷 등 표면 결함을 검사. 전수 기본.', '[]'::jsonb, false),
  ('5b3c0c3a-7709-55ae-a818-92b9d196496e'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '초음파탐상 (UT)', '초음파 반사로 내부 결함을 탐지. 맞댐용접부 내부 검사의 표준(휴대 용이·즉시 판정).', '[]'::jsonb, false),
  ('3430e2c7-f544-5ea5-8ab2-504c8a88dd53'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '방사선투과 (RT)', 'X선·감마선 촬영으로 내부 결함을 필름에 기록. 기록성 우수, 안전관리(피폭) 부담.', '["비교·암기 — 내부 검사 양대: UT(현장 표준·즉시) ↔ RT(기록 남음·통제 필요)."]'::jsonb, false),
  ('b7dbaa68-a8f4-5e19-b734-39ef7de7ebac'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '자분탐상 (MT)', '자화 후 자분을 뿌려 표면·직하 결함을 검출. 강자성체 전용.', '[]'::jsonb, false),
  ('1b9b7fb5-a3ff-5b0e-ac4b-3d91b65f4a2f'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '침투탐상 (PT)', '침투액→현상액으로 표면 열린 결함을 드러냄. 재질 무관·표면 한정.', '[]'::jsonb, false),
  ('3d19067e-ae1c-5051-b9a8-0b852c1630e8'::uuid, '2장 · IV 강재철골 · 3절 · 용접접합 · 용접검사', '용접변형 교정', '용접열 수축으로 생긴 변형을 가열(점·선상 가열)·가압으로 바로잡는 작업. 예방이 우선(용접 순서·구속 계획).', '[]'::jsonb, false),
  ('94758f23-5d8d-5d7b-b410-246410abf132'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '스티프너', '웨브의 좌굴·국부 압괴를 막기 위해 붙이는 보강 판재(하중점·지점부).', '[]'::jsonb, false),
  ('3405b692-67a1-58c0-b2c7-5105b7d6825d'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '거셋플레이트', '가새·트러스 부재를 모아 접합하는 판재. 절점의 힘 전달 매개.', '[]'::jsonb, false),
  ('44148c04-6faa-5966-955c-ded51bbd2964'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '다이어프램', '박스기둥·접합부 내부에 넣는 격막 판. 보 플랜지 힘을 기둥 반대편으로 관통 전달.', '[]'::jsonb, false),
  ('0f56423d-943f-5a1f-b685-6b1341550c04'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '브래킷', '기둥에 미리 용접해 둔 짧은 보 토막. 현장에서는 보와 볼트 접합 — 현장 용접 최소화 전략.', '[]'::jsonb, false),
  ('55ed2f75-c5e8-5a83-8864-fed6bc9afa50'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '메탈터치', '기둥 이음에서 상하 부재 단면을 정밀 가공해 맞대어, 압축력 일부를 접촉면으로 직접 전달하는 상세.', '["이음 볼트·용접량 절감 — 밀착 정밀도가 생명."]'::jsonb, false),
  ('23669ab1-7ae4-575a-84f6-3118f7bb4942'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '스플라이스플레이트', '부재 이음부 양쪽에 덧대어 볼트로 잇는 이음판. 플랜지·웨브 각각 배치.', '[]'::jsonb, false),
  ('77560d31-a0bc-5268-8fa5-35a6571ef70f'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 접합보강부재', '커버플레이트', '플랜지에 덧대어 휨 내력을 키우는 보강판. 모멘트 큰 구간만 보강하는 경제적 수법.', '[]'::jsonb, false),
  ('773aea2d-f59c-59bf-92a7-50a1a3f13553'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 합성구조', '스터드볼트 (전단연결재)', '철골 보 상부에 용접해 콘크리트 슬래브와의 미끄러짐을 막는 머리 달린 볼트.', '["합성보 성립의 필수 조건 — ''둘을 한 몸으로 묶는 못''."]'::jsonb, false),
  ('208a3c69-126b-5e33-ba65-2c8b47d7fd03'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 합성구조', '합성보', '철골 보+콘크리트 슬래브가 전단연결재로 일체 거동하는 보. 슬래브가 압축을 분담 → 철골량 절감.', '[]'::jsonb, false),
  ('a21f9150-abff-59d0-93e7-633a9f040aec'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 합성구조', '합성기둥 (CFT)', '강관 속에 콘크리트를 채운 기둥(Concrete Filled Tube).', '["상승효과: 강관이 콘크리트를 구속(강도·연성↑), 콘크리트가 강관의 국부좌굴을 억제. 거푸집 불필요.", "관리 포인트: 콘크리트 충전성 확인(다이어프램 구멍·압입공법), 내화 설계."]'::jsonb, false),
  ('9b1fea62-b7c1-59b5-ab9e-ecc629fcd377'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '내화피복', '화재열로부터 강재를 보호하는 피복. 강재는 온도 상승 시 강도 급감(내화에 취약)하므로 필수.', '["부위·층수·규모별 내화시간(1~3시간) 요구. ※기준 확인."]'::jsonb, true),
  ('c70c6ec9-855e-5862-97b3-98e526353c4a'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '타설공법 (내화)', '철골 둘레에 콘크리트를 타설해 감싸는 습식 피복. 확실하지만 무겁고 공기 소요.', '[]'::jsonb, false),
  ('e6d53c21-90ca-5203-ad10-ca62af07be1a'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '뿜칠공법', '암면+시멘트 등을 뿜어 붙이는 피복. 경제적·복잡 형상 대응 — 가장 보편적.', '["품질관리: 두께(핀 게이지)·밀도·부착강도 시험. 분진 비산·박리 관리."]'::jsonb, false),
  ('d430a0ec-bf05-5a70-9ce8-7ab69002de6a'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '성형판 붙임공법', '규격 내화판(ALC·규산칼슘판)을 붙이는 건식 피복. 외관 깔끔·품질 균일, 비용↑.', '[]'::jsonb, false),
  ('4464d41e-65b1-56e3-89d9-80e17f535c30'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '내화도료', '화재열에 수십 배 발포·탄화층을 만들어 단열하는 도료(발포성). 노출 철골 디자인에 사용 — 고가.', '[]'::jsonb, false),
  ('d440e29f-440e-5ec9-90e8-b3ab46e688f1'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '건식 · 습식 · 합성 내화피복', '공법 분류: 습식(타설·뿜칠·미장) / 건식(성형판) / 합성(이종 조합) / 도장(내화도료).', '["비교·암기 — ''싸고 빠른 뿜칠, 보이는 곳은 성형판·도료'' — 선택 논리로 정리."]'::jsonb, false),
  ('a6d2109f-ac54-5fc6-96f9-db8b45a7a619'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '데크플레이트 슬래브', '데크+콘크리트 바닥. 내화 성능(피복 두께·와이어메시)과 처짐 관리 포함해 이해.', '[]'::jsonb, false),
  ('a3d7c35e-c9ee-58f0-b14a-9cdcac3c4152'::uuid, '2장 · IV 강재철골 · 4절 · 철골부재내화피복 · 내화피복', '철골 세우기용 가설재', '세우기 중 안전 확보 부재 — 안전대 부착설비(수평구명줄), 추락방지망, 트랩(승강 사다리), 작업발판. 철골 위 보행·고소작업이 최대 위험.', '[]'::jsonb, false)
